    ReadingText(id = "de-read-gruppe-spaziergang", languageID = "de", title = "Die Spaziergruppe", level = "A1", topic = "gesundheit", unitID = "de-foundations-u2", text = "Dienstags organisiert das Viertel einen kostenlosen Spaziergang. Er startet um neun Uhr am Platz und endet am Fluss. Die Gruppe ist gemischt: Studierende, Familien und Rentner sind dabei. Niemand rennt; die Idee ist gehen und reden. Am Ende frühstücken alle, die wollen, gemeinsam in einem Café am Markt. Mia geht seit einem Monat mit und hat schon drei neue Freunde. Sie sagt, es ist die ruhigste Stunde ihrer Woche.", questions = listOf(Exercise(id = "de-read-gruppe-spaziergang-q1", kind = "choice", prompt = "Wann ist der Spaziergang ?", options = listOf("Dienstags", "Montags", "Samstags", "Jeden Tag"), answers = listOf("Dienstags"), explain = "Dienstags organisiert das Viertel einen kostenlosen Spaziergang."), Exercise(id = "de-read-gruppe-spaziergang-q2", kind = "written", prompt = "Um wie viel Uhr startet er ?", options = listOf(), answers = listOf("um neun uhr", "neun uhr"), explain = "Er startet um neun Uhr am Platz."), Exercise(id = "de-read-gruppe-spaziergang-q3", kind = "choice", prompt = "Wer macht mit ?", options = listOf("Studierende, Familien und Rentner", "Nur Studierende", "Nur Rentner", "Nur Familien"), answers = listOf("Studierende, Familien und Rentner"), explain = "Die Gruppe ist gemischt."), Exercise(id = "de-read-gruppe-spaziergang-q4", kind = "choice", prompt = "Was machen alle, die wollen, am Ende ?", options = listOf("Gemeinsam frühstücken", "Zum Fluss rennen", "Nach Hause gehen", "Bus fahren"), answers = listOf("Gemeinsam frühstücken"), explain = "Gemeinsam in einem Café am Markt frühstücken."), Exercise(id = "de-read-gruppe-spaziergang-q5", kind = "written", prompt = "Seit wann geht Mia mit ?", options = listOf(), answers = listOf("einem monat", "1 monat", "seit einem monat"), explain = "Mia geht seit einem Monat mit.")), skills = listOf("reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine")),
    ReadingText(id = "de-read-anzeige-wohnung", languageID = "de", title = "Die Wohnungsanzeige", level = "A2", topic = "wohnungen", unitID = "de-foundations-u4", text = "Helle Zweizimmerwohnung ab September zu mieten. Sie liegt im dritten Stock, mit Aufzug, und hat einen Balkon zum Innenhof, deshalb ist sie ruhig. Das Wohnzimmer ist größer als die Küche, aber die Küche hat ein Fenster. Im Viertel gibt es samstags einen Markt, und die U-Bahn ist fünf Minuten entfernt. Sie ist nicht die billigste in der Gegend, aber die am besten beleuchtete. Eine Kaution von einem Monat wird verlangt, und wer von zu Hause arbeitet, wird bevorzugt – wie die heutigen Besitzer.", questions = listOf(Exercise(id = "de-read-anzeige-wohnung-q1", kind = "choice", prompt = "Wann ist sie verfügbar ?", options = listOf("Ab September", "Ab August", "Sofort", "Im Januar"), answers = listOf("Ab September"), explain = "Ab September zu mieten."), Exercise(id = "de-read-anzeige-wohnung-q2", kind = "choice", prompt = "Warum ist sie ruhig ?", options = listOf("Balkon zum Innenhof", "Im Erdgeschoss", "Keine Nachbarn", "Auf dem Land"), answers = listOf("Balkon zum Innenhof"), explain = "Balkon zum Innenhof, deshalb ruhig."), Exercise(id = "de-read-anzeige-wohnung-q3", kind = "written", prompt = "Wie weit ist die U-Bahn ?", options = listOf(), answers = listOf("fünf minuten", "5 minuten", "fuenf minuten"), explain = "Die U-Bahn ist fünf Minuten entfernt."), Exercise(id = "de-read-anzeige-wohnung-q4", kind = "choice", prompt = "Wie ist sie im Vergleich ?", options = listOf("Nicht die billigste, aber die am besten beleuchtete", "Die billigste", "Die schlechtesten beleuchtete", "Die kleinste"), answers = listOf("Nicht die billigste, aber die am besten beleuchtete"), explain = "Nicht die billigste, aber die am besten beleuchtete."), Exercise(id = "de-read-anzeige-wohnung-q5", kind = "choice", prompt = "Wer wird bevorzugt ?", options = listOf("Jemand, der von zu Hause arbeitet", "Studierende", "Familien mit Kindern", "Rentner"), answers = listOf("Jemand, der von zu Hause arbeitet"), explain = "Wer von zu Hause arbeitet, wird bevorzugt.")), skills = listOf("reading:detail", "reading:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ReadingText(id = "de-read-unvergessliche-reise", languageID = "de", title = "Die unvergessliche Reise", level = "B1", topic = "reisen", unitID = "de-foundations-u6", text = "Letzten Sommer habe ich die Reise gemacht, von der ich immer geträumt habe: fünfzehn Tage in Peru. Ich war schon in Mexiko und Argentinien, aber Südamerika hat mich wieder überrascht. Am dritten Tag bin ich zum Machu Picchu hochgestiegen. Es gab Nebel, deshalb hat man am Anfang nichts gesehen. Dann ist die Sonne langsam herausgekommen und die ganze Stadt ist erschienen. Ich habe nichts gesagt; ich bin nur dageblieben. Im Rückzugszug habe ich eine Familie aus Cusco kennengelernt, und sie haben mich zum Essen eingeladen. « Reisende sagen immer dasselbe », hat die Oma gelacht, « aber diese Suppe ist echt ». Sie hatte recht: es war das beste Essen der Reise. Seitdem, wenn jemand nach einem Reiseziel fragt, sage ich Peru.", questions = listOf(Exercise(id = "de-read-unvergessliche-reise-q1", kind = "choice", prompt = "Wie lange dauerte die Reise ?", options = listOf("Fünfzehn Tage", "Zehn Tage", "Ein Monat", "Drei Tage"), answers = listOf("Fünfzehn Tage"), explain = "Fünfzehn Tage in Peru."), Exercise(id = "de-read-unvergessliche-reise-q2", kind = "written", prompt = "In welchen Ländern war er schon ?", options = listOf(), answers = listOf("mexiko und argentinien"), explain = "Ich war schon in Mexiko und Argentinien."), Exercise(id = "de-read-unvergessliche-reise-q3", kind = "choice", prompt = "Warum hat man am Anfang nichts gesehen ?", options = listOf("Wegen des Nebels", "Weil er geschlossen war", "Wegen starken Regens", "Weil es Nacht war"), answers = listOf("Wegen des Nebels"), explain = "Es gab Nebel, deshalb hat man nichts gesehen."), Exercise(id = "de-read-unvergessliche-reise-q4", kind = "choice", prompt = "Mit wem hat er gegessen ?", options = listOf("Mit einer Familie aus Cusco", "Mit der Oma vom Hotel", "Allein", "Mit Freunden aus dem Zug"), answers = listOf("Mit einer Familie aus Cusco"), explain = "Eine Familie aus Cusco hat mich zum Essen eingeladen."), Exercise(id = "de-read-unvergessliche-reise-q5", kind = "written", prompt = "Was sagt er jetzt, wenn jemand nach einem Reiseziel fragt ?", options = listOf(), answers = listOf("peru"), explain = "Ich sage Peru.")), skills = listOf("reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel")),
    ReadingText(id = "de-read-kolumne-autofrei", languageID = "de", title = "Kolumne: Autofrei!", level = "B2", topic = "meinung", unitID = "de-foundations-u8", text = "Ich finde, wir sollten die Innenstadt autofrei machen. Einerseits würde der Lärm sinken: Die Anwohner des Platzes fordern seit Jahren Ruhe. Andererseits würde die Verschmutzung sinken – sie übersteigt längst die erlaubten Grenzen. Es stimmt, dass der Handel Kunden verlieren fürchtet, aber die Zahlen anderer Städte sagen das Gegenteil: Wo das Auto verschwindet, gehen die Leute mehr spazieren und kaufen mehr. Die Firma, deren Bericht letzten Monat veröffentlicht wurde, hat 15 % mehr Umsatz in autofreien Straßen berechnet. Aus all dem verteidige ich die Maßnahme: Hätten wir den Mut, sie ein Jahr zu versuchen, wollten wir nie zurück.", questions = listOf(Exercise(id = "de-read-kolumne-autofrei-q1", kind = "choice", prompt = "Was ist die These der Kolumne ?", options = listOf("Innenstadt autofrei", "Autobahn verbreitern", "Fahrräder verbieten", "Parkhaus bauen"), answers = listOf("Innenstadt autofrei"), explain = "« Wir sollten die Innenstadt autofrei machen »."), Exercise(id = "de-read-kolumne-autofrei-q2", kind = "written", prompt = "Was übersteigt längst die Grenzen ?", options = listOf(), answers = listOf("die verschmutzung"), explain = "Die Verschmutzung übersteigt die Grenzen."), Exercise(id = "de-read-kolumne-autofrei-q3", kind = "choice", prompt = "Wovor hat der Handel Angst ?", options = listOf("Kunden verlieren", "Mehr Steuern zahlen", "Im Sommer schließen", "Umziehen"), answers = listOf("Kunden verlieren"), explain = "Er fürchtet, Kunden zu verlieren."), Exercise(id = "de-read-kolumne-autofrei-q4", kind = "written", prompt = "Wie viel mehr Umsatz in autofreien Straßen ?", options = listOf(), answers = listOf("15%", "15 %", "fünfzehn prozent"), explain = "15 % mehr Umsatz."), Exercise(id = "de-read-kolumne-autofrei-q5", kind = "choice", prompt = "Was schlägt der Autor am Ende vor ?", options = listOf("Ein Jahr versuchen", "Den Plan vergessen", "Mehr bestrafen", "Nochmal wählen"), answers = listOf("Ein Jahr versuchen"), explain = "« …sie ein Jahr zu versuchen ».")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional")),
    ReadingText(id = "de-read-essay-stadt", languageID = "de", title = "Essay: Die kompakte Stadt", level = "C1", topic = "stadt", unitID = "de-foundations-u9", text = "Ob Großstadt oder Kleinstadt – die Frage klingt alt, doch sie verdient Nuancen. Befürworter der Großstadt verweisen auf Chancen und Vielfalt: Wer dort lebt, findet Arbeit, Kultur und Menschen, die anders denken. Kritiker halten dagegen, dass Mieten steigen und Nachbarschaften anonym werden. Zwar bietet die Kleinstadt Ruhe und günstigen Boden, aber sie kostet oft Mobilität: Wer überallhin fahren muss, verliert Zeit. Aus meiner Sicht entscheidet weniger die Größe als das Angebot: gute Nahversorgung, sichere Radwege, bezahlbare Räume. Sozusagen ist die ideale Stadt die, die Kompromisse überhaupt erst möglich macht. Zusammenfassend bleibt: Statt Ideale zu predigen, sollten Kommunen messen, was die Bewohner tatsächlich brauchen, und genau danach planen. Wer so vorgeht, gewinnt in beiden Welten etwas.", questions = listOf(Exercise(id = "de-read-essay-stadt-q1", kind = "choice", prompt = "Welchen Vorwurf erheben Kritiker gegen die Großstadt ?", options = listOf("Mieten steigen, Nachbarschaften werden anonym", "Es fehlt an Kultur", "Die Arbeit ist langweilig", "Alle denken gleich"), answers = listOf("Mieten steigen, Nachbarschaften werden anonym"), explain = "« …dass Mieten steigen und Nachbarschaften anonym werden »."), Exercise(id = "de-read-essay-stadt-q2", kind = "written", prompt = "Was kostet die Kleinstadt laut Text oft ?", options = listOf(), answers = listOf("mobilität", "mobilitat"), explain = "« …aber sie kostet oft Mobilität »."), Exercise(id = "de-read-essay-stadt-q3", kind = "choice", prompt = "Worauf kommt es laut Text weniger an ?", options = listOf("Auf die Größe", "Auf die Nahversorgung", "Auf sichere Radwege", "Auf bezahlbare Räume"), answers = listOf("Auf die Größe"), explain = "« …entscheidet weniger die Größe als das Angebot »."), Exercise(id = "de-read-essay-stadt-q4", kind = "written", prompt = "Was sollten Kommunen laut Text tun ?", options = listOf(), answers = listOf("messen, was die bewohner brauchen", "messen was die bewohner tatsächlich brauchen", "messen was bewohner tatsachlich brauchen"), explain = "« …sollten Kommunen messen, was die Bewohner tatsächlich brauchen »."), Exercise(id = "de-read-essay-stadt-q5", kind = "choice", prompt = "Welche Funktion hat « Sozusagen » im Text ?", options = listOf("Es markiert eine Formulierung mit Abstand", "Es leitet einen Widerspruch ein", "Es nennt eine Quelle", "Es beendet das Essay"), answers = listOf("Es markiert eine Formulierung mit Abstand"), explain = "« sozusagen » verallgemeinert mit Vorsicht.")), skills = listOf("reading:inference", "grammar:connectors", "writing:argument", "function:express-opinion")),
    ReadingText(id = "de-read-rezension-buch", languageID = "de", title = "Rezension: Raus aus dem Hamsterrad", level = "C1", topic = "kultur", unitID = "de-foundations-u9", text = "Die Debatte « Raus aus dem Hamsterrad » verspricht viel – und hält mehr, als der Titel ahnen lässt. Die Autorin, Ökonomin und ehemalige Journalistin, verbindet Reportagen mit Daten: Zunächst porträtiert sie vier Berufstätige, danach weitet sie den Blick auf Arbeitszeitgesetze. Zwar klingen die Kapitel über Erschöpfung manchmal belehrend, aber die ehrlichen Interviews gleichen das aus. Besonders gelungen ist das Mitteldrittel: Dort zeigt sie, wie eine Fabrik ohne Heroismus auf vier Tage umstellte – keine Revolution, sozusagen Buchführung mit Menschenverstand. Weniger überzeugt das Schlusskapitel, das unbedingt werden will, wo Differenz nötig wäre. Aus meiner Sicht lohnt sich das Buch trotzdem, gerade für Leser, die nuancierte Argumente statt Parolen suchen. Zusammenfassend: eine etwas zu lange, doch selten faire Auseinandersetzung mit unserer Arbeitszeit.", questions = listOf(Exercise(id = "de-read-rezension-buch-q1", kind = "choice", prompt = "Wie bewertet die Rezensentin das Schlusskapitel ?", options = listOf("Es will unbedingt sein, wo Differenz nötig wäre", "Es ist besonders gelungen", "Es fehlt vollständig", "Es ist zu kurz geraten"), answers = listOf("Es will unbedingt sein, wo Differenz nötig wäre"), explain = "« …das unbedingt werden will, wo Differenz nötig wäre »."), Exercise(id = "de-read-rezension-buch-q2", kind = "written", prompt = "Welches Beispiel zeigt das Mitteldrittel ?", options = listOf(), answers = listOf("eine fabrik, die auf vier tage umstellte", "eine fabrik auf vier tage", "eine fabrik"), explain = "« …wie eine Fabrik … auf vier Tage umstellte »."), Exercise(id = "de-read-rezension-buch-q3", kind = "choice", prompt = "Was gleicht die schwächeren Kapitel aus ?", options = listOf("Die ehrlichen Interviews", "Die Datenlage", "Die Titelwahl", "Die Arbeitszeitgesetze"), answers = listOf("Die ehrlichen Interviews"), explain = "« …aber die ehrlichen Interviews gleichen das aus »."), Exercise(id = "de-read-rezension-buch-q4", kind = "written", prompt = "Für welche Leser lohnt sich das Buch laut Text ?", options = listOf(), answers = listOf("leser, die nuancierte argumente suchen", "leser die nuancierte argumente statt parolen suchen"), explain = "« …für Leser, die nuancierte Argumente statt Parolen suchen »."), Exercise(id = "de-read-rezension-buch-q5", kind = "choice", prompt = "Welches Urteil steht im letzten Satz ?", options = listOf("Etwas zu lang, doch selten fair", "Radikal und revolutionär", "Kurz und präzise", "Belehrend und unfair"), answers = listOf("Etwas zu lang, doch selten fair"), explain = "« eine etwas zu lange, doch selten faire Auseinandersetzung ».")), skills = listOf("reading:inference", "reading:scan", "vocab:collocations", "function:express-opinion")),
    ReadingText(id = "de-read-brief-leitung", languageID = "de", title = "Brief an die Leitung", level = "C1", topic = "arbeit", unitID = "de-foundations-u9", text = "Sehr geehrte Frau Mertens,\n\nich wende mich heute an Sie, weil ich eine Anregung aus dem Support-Team weiterleiten möchte. Das Team schlägt vor, die Schichtpläne künftig zwei Wochen im Voraus zu veröffentlichen. Zwar ist das derzeit aus organisatorischen Gründen schwierig, jedoch berichten mehrere Kolleginnen, dass kurzfristige Änderungen die Kinderbetreuung belasten. Aus meiner Sicht wäre ein Kompromiss denkbar: feste Grundschichten, die nur in Ausnahmefällen wechseln. Ich wollte mich zudem erkundigen, ob Sie ein kurzes Gespräch in der nächsten Woche einträumen könnten; dabei können wir die Details gerne klären. Ich danke Ihnen im Voraus für Ihre Rückmeldung und stehe für Rückfragen selbstverständlich zur Verfügung.\n\nMit freundlichen Grüßen,\nJonas Berger", questions = listOf(Exercise(id = "de-read-brief-leitung-q1", kind = "choice", prompt = "Was schlägt das Team vor ?", options = listOf("Schichtpläne zwei Wochen im Voraus veröffentlichen", "Das Team verkleinern", "Die Kinderbetreuung übernehmen", "Alle Schichten streichen"), answers = listOf("Schichtpläne zwei Wochen im Voraus veröffentlichen"), explain = "« …die Schichtpläne künftig zwei Wochen im Voraus zu veröffentlichen »."), Exercise(id = "de-read-brief-leitung-q2", kind = "written", prompt = "Was belasten kurzfristige Änderungen laut Brief ?", options = listOf(), answers = listOf("die kinderbetreuung", "kinderbetreuung"), explain = "« …dass kurzfristige Änderungen die Kinderbetreuung belasten »."), Exercise(id = "de-read-brief-leitung-q3", kind = "written", prompt = "Welchen Kompromiss schlägt Jonas vor ?", options = listOf(), answers = listOf("feste grundschichten", "feste grundschichten, die nur in ausnahmefällen wechseln", "feste grundschichten, die nur in ausnahmefaellen wechseln"), explain = "« feste Grundschichten, die nur in Ausnahmefällen wechseln »."), Exercise(id = "de-read-brief-leitung-q4", kind = "choice", prompt = "Warum schreibt Jonas ?", options = listOf("Um eine Anregung weiterzugeben und ein Gespräch vorzuschlagen", "Um zu kündigen", "Um eine Rechnung zu klären", "Um Urlaub zu beantragen"), answers = listOf("Um eine Anregung weiterzugeben und ein Gespräch vorzuschlagen"), explain = "Anregung + Gesprächsbitte sind der Zweck des Briefs."), Exercise(id = "de-read-brief-leitung-q5", kind = "written", prompt = "Welche formelle Grußformel steht am Ende ?", options = listOf(), answers = listOf("mit freundlichen grüßen", "mit freundlichen grussen"), explain = "« Mit freundlichen Grüßen » – Standard am Briefende.")), skills = listOf("reading:detail", "vocab:work", "grammar:connectors", "function:express-opinion")),
    ReadingText(id = "de-read-anzeige-mitbewohner", languageID = "de", title = "Anzeige: Mitbewohner gesucht", level = "A1", topic = "Wohnen", unitID = "de-foundations-u10", text = "Zimmer frei! Ich suche einen Mitbewohner für meine Wohnung. Die Wohnung liegt im zweiten Stock und hat vier Zimmer. Dein Zimmer ist 18 Quadratmeter groß und sehr hell. Es gibt eine Küche, ein Bad und einen kleinen Balkon. Auf dem Balkon stehen zwei Stühle. Ich heiße Anna, bin 27 Jahre alt und arbeite als Verkäuferin. Ich bin ruhig und ordentlich. Mein Sofa ist alt, aber gemütlich. Schreib mir!", questions = listOf(Exercise(id = "de-read-anzeige-mitbewohner-q1", kind = "choice", prompt = "Was sucht Anna ?", options = listOf("Einen Mitbewohner", "Eine neue Wohnung", "Einen Job", "Ein Sofa"), answers = listOf("Einen Mitbewohner"), explain = "Ich suche einen Mitbewohner für meine Wohnung."), Exercise(id = "de-read-anzeige-mitbewohner-q2", kind = "written", prompt = "Wie groß ist das Zimmer ?", options = listOf(), answers = listOf("18 quadratmeter", "achtzehn quadratmeter", "18 qm"), explain = "Dein Zimmer ist 18 Quadratmeter groß."), Exercise(id = "de-read-anzeige-mitbewohner-q3", kind = "choice", prompt = "Was gibt es auf dem Balkon ?", options = listOf("Zwei Stühle", "Ein Sofa", "Einen Tisch", "Blumen"), answers = listOf("Zwei Stühle"), explain = "Auf dem Balkon stehen zwei Stühle."), Exercise(id = "de-read-anzeige-mitbewohner-q4", kind = "written", prompt = "Wie alt ist Anna ?", options = listOf(), answers = listOf("27", "27 jahre", "sie ist 27 jahre alt"), explain = "Anna ist 27 Jahre alt."), Exercise(id = "de-read-anzeige-mitbewohner-q5", kind = "choice", prompt = "Wie ist Anna ?", options = listOf("Ruhig und ordentlich", "Laut und unordentlich", "Nett, aber laut", "Sehr sportlich"), answers = listOf("Ruhig und ordentlich"), explain = "Ich bin ruhig und ordentlich.")), skills = listOf("reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people")),
    ReadingText(id = "de-read-nachricht-gruppe", languageID = "de", title = "Nachrichten fürs Wochenende", level = "A1", topic = "Wochenende", unitID = "de-foundations-u13", text = "Gruppe „Wochenende“ — Kim: Es regnet am Samstag. Ich bleibe zu Hause und lese. Ich lese immer am Wochenende. Sam: Ich koche gern. Wer kommt zum Essen ? Wir kochen um 18 Uhr. Mia: Ich bin dabei! Ich spiele oft Volleyball, aber am Samstag nie. Im Sommer spiele ich jeden Tag. Sam: Super. Bis Samstag! — Kim: Ich komme auch. Bis dann!", questions = listOf(Exercise(id = "de-read-nachricht-gruppe-q1", kind = "choice", prompt = "Wie ist das Wetter am Samstag ?", options = listOf("Es regnet", "Es schneit", "Es ist sonnig", "Es ist warm"), answers = listOf("Es regnet"), explain = "Kim: Es regnet am Samstag."), Exercise(id = "de-read-nachricht-gruppe-q2", kind = "written", prompt = "Was macht Mia oft ?", options = listOf(), answers = listOf("volleyball", "sie spielt volleyball", "volleyball spielen"), explain = "Ich spiele oft Volleyball, aber am Samstag nie."), Exercise(id = "de-read-nachricht-gruppe-q3", kind = "choice", prompt = "Wann kocht Sam ?", options = listOf("Um 18 Uhr", "Um 8 Uhr", "Am Morgen", "Um 20 Uhr"), answers = listOf("Um 18 Uhr"), explain = "Wir kochen um 18 Uhr."), Exercise(id = "de-read-nachricht-gruppe-q4", kind = "written", prompt = "Was macht Kim immer am Wochenende ?", options = listOf(), answers = listOf("lesen", "sie liest", "kim liest"), explain = "Ich lese immer am Wochenende."), Exercise(id = "de-read-nachricht-gruppe-q5", kind = "choice", prompt = "Wer kommt zum Essen ?", options = listOf("Kim und Mia", "Nur Mia", "Niemand", "Sam und Kim"), answers = listOf("Kim und Mia"), explain = "Mia: Ich bin dabei! — Kim: Ich komme auch.")), skills = listOf("reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs")),
    ReadingText(id = "en-read-neighbour-note", languageID = "en", title = "A note from your neighbour", level = "A1", topic = "home", unitID = "en-foundations-u2", text = "Hi! I'm Marta, from flat 4B. I'm your new neighbour. I'm a nurse, and I work at the city hospital on Mondays, Tuesdays and weekends. My cat's name is Luna — she's grey and very friendly, but please don't feed her! My number is 655 214 890. Call me if there's any problem with the building. The lift is very old, so please close both doors. Thank you — and welcome! Let's have a coffee one day. Marta", questions = listOf(Exercise(id = "en-read-neighbour-note-q1", kind = "choice", prompt = "Where is Marta from?", options = listOf("Flat 4B", "Flat 2A", "The city hospital", "The ground floor"), answers = listOf("Flat 4B"), explain = "She writes: I'm Marta, from flat 4B."), Exercise(id = "en-read-neighbour-note-q2", kind = "choice", prompt = "When does Marta work?", options = listOf("Mondays, Tuesdays and weekends", "Only at night", "Every morning", "On Fridays"), answers = listOf("Mondays, Tuesdays and weekends"), explain = "She works on Mondays, Tuesdays and weekends."), Exercise(id = "en-read-neighbour-note-q3", kind = "written", prompt = "What is her cat's name?", options = listOf(), answers = listOf("luna"), explain = "Her cat's name is Luna."), Exercise(id = "en-read-neighbour-note-q4", kind = "choice", prompt = "What does she ask about the lift?", options = listOf("Close both doors", "Don't use it", "Clean it every week", "Call her before using it"), answers = listOf("Close both doors"), explain = "The lift is old, so please close both doors."), Exercise(id = "en-read-neighbour-note-q5", kind = "choice", prompt = "What does Marta suggest at the end?", options = listOf("Having a coffee one day", "Feeding the cat", "A building meeting", "Nothing"), answers = listOf("Having a coffee one day"), explain = "She writes: Let's have a coffee one day.")), skills = listOf("reading:detail", "reading:scan", "grammar:possessives", "vocab:home")),
    ReadingText(id = "en-read-bus-12", languageID = "en", title = "Bus number 12", level = "A1", topic = "transport", unitID = "en-foundations-u4", text = "BUS 12 — CITY CENTRE — AIRPORT. First bus: 6:10. Last bus: 23:40. Buses leave every 20 minutes from Station Square. A single ticket is 2 euros; a day ticket is 5 euros. You can buy tickets from the driver or from the machine at the stop. The bus to the airport takes about 35 minutes. Big suitcases are free, but dogs need a ticket! The night bus N12 leaves at 1:20 and 3:20, from the same stop. For information, call 900 12 12 12 or ask at the station office (open 7:00–21:00).", questions = listOf(Exercise(id = "en-read-bus-12-q1", kind = "written", prompt = "What time is the first bus?", options = listOf(), answers = listOf("6:10", "at 6:10", "six ten"), explain = "The first bus is at 6:10."), Exercise(id = "en-read-bus-12-q2", kind = "choice", prompt = "How often do buses leave?", options = listOf("Every 20 minutes", "Every hour", "Every 35 minutes", "Twice a day"), answers = listOf("Every 20 minutes"), explain = "Buses leave every 20 minutes from Station Square."), Exercise(id = "en-read-bus-12-q3", kind = "choice", prompt = "How much is a day ticket?", options = listOf("5 euros", "2 euros", "12 euros", "Free"), answers = listOf("5 euros"), explain = "A day ticket is 5 euros."), Exercise(id = "en-read-bus-12-q4", kind = "choice", prompt = "Who needs a ticket?", options = listOf("Dogs", "Children", "People with suitcases", "Students"), answers = listOf("Dogs"), explain = "Suitcases are free, but dogs need a ticket!"), Exercise(id = "en-read-bus-12-q5", kind = "written", prompt = "How long does the airport bus take?", options = listOf(), answers = listOf("35 minutes", "about 35 minutes", "35 min"), explain = "The bus to the airport takes about 35 minutes.")), skills = listOf("reading:scan", "reading:detail", "vocab:transport", "listening:number-time")),
    ReadingText(id = "en-read-annas-week", languageID = "en", title = "Anna's week", level = "A1", topic = "routine", unitID = "en-foundations-u3", text = "Anna works in a bookshop from Tuesday to Saturday. On Mondays she doesn't work — she cleans her flat in the morning and plays tennis with her sister in the afternoon. She always gets up at seven and walks to work; the bookshop opens at nine. In the evening she cooks, but on Thursdays she eats with her parents. On Sundays the bookshop is closed, and Anna likes to sleep late, read in the park and call her grandmother. Her grandmother always asks the same question: 'Do you eat enough fruit, Anna?' And Anna always says yes.", questions = listOf(Exercise(id = "en-read-annas-week-q1", kind = "choice", prompt = "When does Anna work?", options = listOf("Tuesday to Saturday", "Monday to Friday", "Every day", "Only weekends"), answers = listOf("Tuesday to Saturday"), explain = "She works from Tuesday to Saturday."), Exercise(id = "en-read-annas-week-q2", kind = "written", prompt = "What does she do on Monday afternoons?", options = listOf(), answers = listOf("plays tennis", "she plays tennis", "play tennis with her sister"), explain = "She plays tennis with her sister."), Exercise(id = "en-read-annas-week-q3", kind = "choice", prompt = "How does she go to work?", options = listOf("She walks", "By bus", "By bike", "By car"), answers = listOf("She walks"), explain = "She always gets up at seven and walks to work."), Exercise(id = "en-read-annas-week-q4", kind = "choice", prompt = "When does she eat with her parents?", options = listOf("On Thursdays", "On Mondays", "Every evening", "On Sundays"), answers = listOf("On Thursdays"), explain = "On Thursdays she eats with her parents."), Exercise(id = "en-read-annas-week-q5", kind = "written", prompt = "Who always asks about fruit?", options = listOf(), answers = listOf("her grandmother", "grandmother", "her grandma"), explain = "Her grandmother always asks the same question.")), skills = listOf("reading:detail", "reading:gist", "grammar:frequency-adverbs", "vocab:daily-routine")),
    ReadingText(id = "en-read-lost-dog", languageID = "en", title = "The poster on the tree", level = "A1", topic = "town", text = "LOST DOG — HAVE YOU SEEN TOBY? Toby is a small brown dog. He is eight years old, and he is very friendly, but he is old and a little deaf — he doesn't hear very well. He ran away from Elm Street on Friday evening. He has got a red collar with a phone number. Toby is afraid of loud noises, so please don't chase him. If you see him, please call Sandra on 611 404 404 (day or night). There is a reward: 100 euros. Thank you for helping Toby come home!", questions = listOf(Exercise(id = "en-read-lost-dog-q1", kind = "written", prompt = "What is the dog's name?", options = listOf(), answers = listOf("toby"), explain = "The dog's name is Toby."), Exercise(id = "en-read-lost-dog-q2", kind = "choice", prompt = "What does Toby look like?", options = listOf("Small and brown", "Big and black", "White and old", "Brown and young"), answers = listOf("Small and brown"), explain = "Toby is a small brown dog."), Exercise(id = "en-read-lost-dog-q3", kind = "choice", prompt = "Why shouldn't you chase him?", options = listOf("He is afraid of loud noises", "He is very fast", "He bites", "He is sleeping"), answers = listOf("He is afraid of loud noises"), explain = "Toby is afraid of loud noises, so please don't chase him."), Exercise(id = "en-read-lost-dog-q4", kind = "written", prompt = "When did he run away?", options = listOf(), answers = listOf("on friday evening", "friday evening", "friday"), explain = "He ran away from Elm Street on Friday evening."), Exercise(id = "en-read-lost-dog-q5", kind = "choice", prompt = "What does Toby have got?", options = listOf("A red collar with a phone number", "A blue jacket", "A name tag on his ear", "Nothing"), answers = listOf("A red collar with a phone number"), explain = "He has got a red collar with a phone number.")), skills = listOf("reading:detail", "reading:inference", "grammar:can", "vocab:town")),
    ReadingText(id = "en-read-cafe-menu", languageID = "en", title = "The little café menu", level = "A1", topic = "food", text = "THE LITTLE CAFÉ — OPEN 7:30 TO 18:00, MONDAY TO SATURDAY. Coffee: espresso 1.20 — latte 1.80 — hot chocolate 2.50. Breakfast (until 12:00): toast with tomato 2.20 — croissant 1.50 — full breakfast with eggs, bacon and juice 6.90. Lunch: soup of the day 3.50 — cheese sandwich 4.20 — chicken salad 5.90 — today's special: fish and rice 7.50. Cakes: apple cake 2.80 — lemon cake 2.80. We have free water — just ask! Dogs are welcome on the terrace. Card payments from 3 euros. Follow us online for the soup of the day!", questions = listOf(Exercise(id = "en-read-cafe-menu-q1", kind = "choice", prompt = "When is the café open?", options = listOf("7:30 to 18:00, Monday to Saturday", "Every day until midnight", "Only in the morning", "Sundays too"), answers = listOf("7:30 to 18:00, Monday to Saturday"), explain = "It is open 7:30 to 18:00, Monday to Saturday."), Exercise(id = "en-read-cafe-menu-q2", kind = "written", prompt = "How much is a latte?", options = listOf(), answers = listOf("1.80", "1,80", "one euro eighty"), explain = "A latte is 1.80."), Exercise(id = "en-read-cafe-menu-q3", kind = "choice", prompt = "What time does breakfast end?", options = listOf("At 12:00", "At 7:30", "At 18:00", "All day"), answers = listOf("At 12:00"), explain = "Breakfast is served until 12:00."), Exercise(id = "en-read-cafe-menu-q4", kind = "choice", prompt = "Which lunch costs 7.50?", options = listOf("Fish and rice", "Cheese sandwich", "Chicken salad", "Soup of the day"), answers = listOf("Fish and rice"), explain = "Today's special — fish and rice — is 7.50."), Exercise(id = "en-read-cafe-menu-q5", kind = "choice", prompt = "What is free in the café?", options = listOf("Water", "Coffee", "Cakes", "Wifi"), answers = listOf("Water"), explain = "We have free water — just ask!")), skills = listOf("reading:scan", "reading:detail", "vocab:food", "function:order-food")),
    ReadingText(id = "en-read-postcard-london", languageID = "en", title = "A postcard from London", level = "A1", topic = "travel", unitID = "en-foundations-now", text = "Dear Paco, greetings from London! I'm writing this from a small café near the river. It's raining (of course!), so I'm wearing my new blue coat. My friend Clara is sitting next to me and planning our afternoon. This morning we are visiting the British Museum — it's free! — and this afternoon we're walking to Big Ben. In the evening, Clara's cousin is cooking dinner for us. London is expensive, but the museums are free and the parks are beautiful. I'm learning a lot of English every day. See you on Sunday! Elena", questions = listOf(Exercise(id = "en-read-postcard-london-q1", kind = "choice", prompt = "Where is Elena writing from?", options = listOf("A small café near the river", "The British Museum", "Her hotel", "Big Ben"), answers = listOf("A small café near the river"), explain = "She is writing from a small café near the river."), Exercise(id = "en-read-postcard-london-q2", kind = "written", prompt = "What's the weather doing?", options = listOf(), answers = listOf("it's raining", "it is raining", "raining"), explain = "It's raining — of course!"), Exercise(id = "en-read-postcard-london-q3", kind = "choice", prompt = "What is she wearing?", options = listOf("A new blue coat", "An old red coat", "A yellow scarf", "A green hat"), answers = listOf("A new blue coat"), explain = "She's wearing her new blue coat."), Exercise(id = "en-read-postcard-london-q4", kind = "choice", prompt = "What are they doing this morning?", options = listOf("Visiting the British Museum", "Cooking dinner", "Walking to Big Ben", "Shopping"), answers = listOf("Visiting the British Museum"), explain = "This morning they are visiting the British Museum."), Exercise(id = "en-read-postcard-london-q5", kind = "choice", prompt = "Who is cooking dinner?", options = listOf("Clara's cousin", "Elena", "Clara", "Paco"), answers = listOf("Clara's cousin"), explain = "In the evening, Clara's cousin is cooking dinner for them.")), skills = listOf("reading:gist", "grammar:present-continuous", "vocab:travel", "vocab:weather")),
    ReadingText(id = "en-read-flat-advert", languageID = "en", title = "Two flats, one advert", level = "A2", topic = "home", text = "FLAT A — Ríos 14, 3rd floor. 65 m², two bedrooms, one bathroom. Modern kitchen, small balcony, 4th floor without lift. €790/month. Quiet street, 10 minutes from the university by bike. Perfect for students or a young couple. Flat B — Avda del Sol 3, 1st floor WITH lift. 80 m², three bedrooms, bright living room, older building but recently painted. €950/month. 5 minutes from the metro. The agency says: 'Flat A is smaller but cheaper; Flat B is more comfortable and better connected. Flat A gets more sun in the afternoon; Flat B is quieter at night. Both are available from the 1st. Visits on Saturdays, 10:00–14:00. Call 91 555 0199 for more information.'", questions = listOf(Exercise(id = "en-read-flat-advert-q1", kind = "choice", prompt = "Which flat is bigger?", options = listOf("Flat B", "Flat A", "They're the same", "The advert doesn't say"), answers = listOf("Flat B"), explain = "Flat B is 80 m²; Flat A is 65 m²."), Exercise(id = "en-read-flat-advert-q2", kind = "written", prompt = "How much is Flat A per month?", options = listOf(), answers = listOf("790 euros", "€790", "790"), explain = "Flat A is €790/month."), Exercise(id = "en-read-flat-advert-q3", kind = "choice", prompt = "Which flat has a lift?", options = listOf("Flat B", "Flat A", "Neither", "Both"), answers = listOf("Flat B"), explain = "Flat B is on the 1st floor WITH lift; Flat A is 4th floor without lift."), Exercise(id = "en-read-flat-advert-q4", kind = "choice", prompt = "What does the advert say about Flat A in the afternoon?", options = listOf("It gets more sun", "It's quieter", "It's hotter", "It's noisier"), answers = listOf("It gets more sun"), explain = "Flat A gets more sun in the afternoon."), Exercise(id = "en-read-flat-advert-q5", kind = "written", prompt = "When can you visit the flats?", options = listOf(), answers = listOf("saturdays 10:00-14:00", "on saturdays", "saturday mornings"), explain = "Visits on Saturdays, 10:00–14:00.")), skills = listOf("reading:detail", "reading:scan", "grammar:comparatives", "grammar:superlatives", "vocab:home")),
    ReadingText(id = "en-read-weekend-list", languageID = "en", title = "What's on this weekend", level = "A2", topic = "free time", text = "CITY WEEKEND GUIDE — SATURDAY & SUNDAY. SATURDAY: Free yoga in Central Park at 9:00 (bring your own mat). Farmers' market at the old port, 8:00–14:00 — the strawberries are the best in the region! River boat tour every hour, €6. SUNDAY: Photography exhibition at the Modern Museum — free entry before 12:00. Charity run: 5 or 10 km, start at 10:30 from the Town Hall. You should register online before Saturday night. Evening open-air cinema at 21:30 — tonight's film is a classic; blankets are free, hot drinks cost €1. Rain plan: all Sunday activities move to the Cultural Centre. Have a great weekend!", questions = listOf(Exercise(id = "en-read-weekend-list-q1", kind = "choice", prompt = "What time does free yoga start on Saturday?", options = listOf("At 9:00", "At 8:00", "At 10:30", "At 21:30"), answers = listOf("At 9:00"), explain = "Free yoga in Central Park at 9:00."), Exercise(id = "en-read-weekend-list-q2", kind = "written", prompt = "According to the guide, what are the best strawberries in the region?", options = listOf(), answers = listOf("the farmers market", "farmers market", "the market at the old port"), explain = "The farmers' market strawberries are the best in the region."), Exercise(id = "en-read-weekend-list-q3", kind = "choice", prompt = "When is the museum free?", options = listOf("Before 12:00 on Sunday", "All weekend", "Never", "On Saturday morning"), answers = listOf("Before 12:00 on Sunday"), explain = "Free entry before 12:00."), Exercise(id = "en-read-weekend-list-q4", kind = "written", prompt = "What should you do before Saturday night for the charity run?", options = listOf(), answers = listOf("register online", "register", "you should register online"), explain = "You should register online before Saturday night."), Exercise(id = "en-read-weekend-list-q5", kind = "choice", prompt = "What happens if it rains on Sunday?", options = listOf("Activities move to the Cultural Centre", "Everything is cancelled", "The cinema closes", "The run is shorter"), answers = listOf("Activities move to the Cultural Centre"), explain = "The rain plan: all Sunday activities move indoors.")), skills = listOf("reading:scan", "reading:detail", "grammar:going-to", "grammar:modal-should", "vocab:hobbies")),
    ReadingText(id = "en-read-doctor-advice", languageID = "en", title = "The doctor's advice", level = "A2", topic = "health", text = "Patient information sheet — Tiredness. Are you sleeping badly? Many office workers feel tired all week. Our doctors say: You shouldn't drink coffee after four o'clock. You should go to bed at the same time every night — your body loves routine. You mustn't use screens in bed: the light tells your brain it's daytime. You don't have to sleep eight hours exactly — seven can be enough if it's good sleep. Exercise helps, but not just before bed: a walk at lunchtime is better than a run at ten at night. If you're still tired after two weeks of good habits, you should book an appointment. Sleep well!", questions = listOf(Exercise(id = "en-read-doctor-advice-q1", kind = "choice", prompt = "When shouldn't you drink coffee?", options = listOf("After four o'clock", "In the morning", "Before lunch", "With food"), answers = listOf("After four o'clock"), explain = "You shouldn't drink coffee after four o'clock."), Exercise(id = "en-read-doctor-advice-q2", kind = "written", prompt = "What mustn't you do in bed?", options = listOf(), answers = listOf("use screens", "use screens in bed", "look at screens"), explain = "You mustn't use screens in bed."), Exercise(id = "en-read-doctor-advice-q3", kind = "choice", prompt = "How much sleep do you have to get?", options = listOf("Seven can be enough", "Exactly eight hours", "Nine hours", "Ten hours"), answers = listOf("Seven can be enough"), explain = "You don't have to sleep eight hours — seven is fine if it's good sleep."), Exercise(id = "en-read-doctor-advice-q4", kind = "choice", prompt = "When is exercise better?", options = listOf("A walk at lunchtime", "A run at ten at night", "Never", "Just before bed"), answers = listOf("A walk at lunchtime"), explain = "A walk at lunchtime is better than a run at night."), Exercise(id = "en-read-doctor-advice-q5", kind = "written", prompt = "What should you do if good habits don't work after two weeks?", options = listOf(), answers = listOf("book an appointment", "book a doctors appointment", "see a doctor", "you should book an appointment"), explain = "You should book an appointment.")), skills = listOf("reading:detail", "grammar:modal-should", "grammar:modal-must-have-to", "vocab:health")),
    ReadingText(id = "en-read-complaint-email", languageID = "en", title = "A short complaint email", level = "A2", topic = "problems", text = "Subject: Order 4492 — wrong size. Dear Customer Service, I ordered a winter jacket (size M, order 4492) on 3 October, and it arrived on Thursday. Unfortunately, you sent size S instead of M. I checked the box and the label — both say S. I like the jacket and I want to keep it, so I would like to exchange it for the correct size. Should I send the small one back first, or do you send the new one and collect the other? The return service near me is only open in the mornings, so a home collection would be easier. I have to say the delivery was very fast — that part was perfect! I look forward to your reply. Best regards, Daniel Ortiz (customer since 2021)", questions = listOf(Exercise(id = "en-read-complaint-email-q1", kind = "choice", prompt = "What was wrong with the order?", options = listOf("The size", "The colour", "The price", "The delivery day"), answers = listOf("The size"), explain = "They sent size S instead of M."), Exercise(id = "en-read-complaint-email-q2", kind = "choice", prompt = "What does Daniel want?", options = listOf("To exchange it for the correct size", "His money back", "A discount", "A different jacket"), answers = listOf("To exchange it for the correct size"), explain = "He likes the jacket and wants to exchange it."), Exercise(id = "en-read-complaint-email-q3", kind = "written", prompt = "What question does Daniel ask about the return?", options = listOf(), answers = listOf("should he send it back first", "send back first or home collection", "who collects the small one"), explain = "Should he send it first, or do they collect it?"), Exercise(id = "en-read-complaint-email-q4", kind = "choice", prompt = "What was perfect, according to Daniel?", options = listOf("The delivery", "The price", "The box", "The label"), answers = listOf("The delivery"), explain = "He has to admit: the delivery was very fast."), Exercise(id = "en-read-complaint-email-q5", kind = "written", prompt = "How long has Daniel been a customer?", options = listOf(), answers = listOf("since 2021", "five years", "since two thousand twenty one"), explain = "Customer since 2021.")), skills = listOf("reading:detail", "function:solve-problems", "grammar:modal-should", "grammar:modal-must-have-to", "writing:email"), exposureSkills = listOf("grammar:past-simple-irregular")),
    ReadingText(id = "en-read-hotel-review", languageID = "en", title = "A review: The Glass House Hotel", level = "B1", topic = "travel", text = "★★★☆☆ The Glass House Hotel looks spectacular online, and to be fair, the reality is close: the glass roof over the lobby is stunning, and our room, which faced the harbour, had the best view of the week. However, several things annoyed me. Although the website promises 'quiet rooms', ours was above the bar, and the music went on until one in the morning. The breakfast, which is served until ten, ran out of almost everything by nine on both mornings. The staff, who were genuinely kind, tried to help — they moved us on the second night and offered free coffee. Would I return? If they soundproof the bar, yes. If not, I'll pay ten euros more for the hotel next door, which, according to friends, is quieter and includes breakfast.", questions = listOf(Exercise(id = "en-read-hotel-review-q1", kind = "choice", prompt = "What did the reviewer love about the room?", options = listOf("The view of the harbour", "The glass roof", "The bar downstairs", "The breakfast"), answers = listOf("The view of the harbour"), explain = "Their room faced the harbour and had the best view of the week."), Exercise(id = "en-read-hotel-review-q2", kind = "written", prompt = "Why didn't they sleep well?", options = listOf(), answers = listOf("the music from the bar", "the bar music", "music until one in the morning"), explain = "The room was above the bar; music until one."), Exercise(id = "en-read-hotel-review-q3", kind = "choice", prompt = "What did the staff do?", options = listOf("They moved them and offered free coffee", "Nothing", "They refunded the night", "They closed the bar"), answers = listOf("They moved them and offered free coffee"), explain = "The staff, who were genuinely kind, moved them on the second night."), Exercise(id = "en-read-hotel-review-q4", kind = "choice", prompt = "What will make the reviewer return?", options = listOf("Soundproofing the bar", "A discount", "A better view", "An earlier breakfast"), answers = listOf("Soundproofing the bar"), explain = "If they soundproof the bar, yes."), Exercise(id = "en-read-hotel-review-q5", kind = "written", prompt = "According to friends, what is the hotel next door like?", options = listOf(), answers = listOf("quieter and includes breakfast", "quieter", "quieter and with breakfast included"), explain = "Quieter and includes breakfast.")), skills = listOf("reading:inference", "grammar:relative-clauses", "grammar:first-conditional", "grammar:connectors", "vocab:travel")),
    ReadingText(id = "en-read-remote-work", languageID = "en", title = "Is remote work working?", level = "B1", topic = "work", text = "Five years ago, most offices insisted that great work needed a shared room. Today, that idea is under review. Companies which moved to hybrid schedules report fewer sick days and lower costs; employees save hours of commuting every week, and many say they are more productive at home. However, the picture is not simple. New employees who have never met their teams in person often feel invisible, and creative work — the kind that grows from accidental corridor conversations — seems harder online. Although younger workers usually prefer flexibility, some admit that home offices blur the line between life and work until answering emails at midnight feels normal again. Perhaps the honest answer is that remote work works when the work is remote-shaped: independent, measured by results, written down. For everything else, the corridor still has value.", questions = listOf(Exercise(id = "en-read-remote-work-q1", kind = "choice", prompt = "What do companies with hybrid schedules report?", options = listOf("Fewer sick days and lower costs", "Higher costs", "Worse productivity", "Nothing"), answers = listOf("Fewer sick days and lower costs"), explain = "They report fewer sick days and lower costs."), Exercise(id = "en-read-remote-work-q2", kind = "written", prompt = "Who often feels invisible?", options = listOf(), answers = listOf("new employees", "new employees who have never met their teams", "new people"), explain = "New employees who have never met their teams in person."), Exercise(id = "en-read-remote-work-q3", kind = "choice", prompt = "What kind of work seems harder online?", options = listOf("Creative work", "Administrative work", "Written work", "Independent work"), answers = listOf("Creative work"), explain = "Work that grows from corridor conversations seems harder online."), Exercise(id = "en-read-remote-work-q4", kind = "written", prompt = "What negative habit can return with home offices?", options = listOf(), answers = listOf("answering emails at midnight", "answering emails late at night", "working at midnight"), explain = "Answering emails at midnight can feel normal again."), Exercise(id = "en-read-remote-work-q5", kind = "choice", prompt = "When does remote work work, according to the article?", options = listOf("When the work is remote-shaped", "Never", "Always", "Only for managers"), answers = listOf("When the work is remote-shaped"), explain = "Independent, measured by results, written down.")), skills = listOf("reading:inference", "grammar:relative-clauses", "grammar:connectors", "grammar:present-perfect", "vocab:work")),
    ReadingText(id = "en-read-missing-keys", languageID = "en", title = "The missing keys", level = "B1", topic = "stories", text = "Marta was making coffee when she realised the flat was silent — the specific, heavy silence of a missing object. Her keys, which always lived in the blue bowl by the door, were gone. She looked in her coat, in yesterday's bag, under the sofa where small things liked to disappear. Nothing. While she was searching, her phone buzzed: a message from Diego, her downstairs neighbour. 'Are you missing something shiny? A little thief brought me a present.' His cat, Luna, had a habit of collecting small metal objects, and although Marta had never caught her in the act, the evidence was now clear: three keys, a bottle opener and last winter's missing earring. Marta went downstairs, laughed until her sides hurt, and installed a hook high on the wall. The bowl stayed empty from that day; Luna, however, kept bringing gifts.", questions = listOf(Exercise(id = "en-read-missing-keys-q1", kind = "choice", prompt = "What was Marta doing when she noticed the silence?", options = listOf("Making coffee", "Searching the sofa", "Reading a message", "Going downstairs"), answers = listOf("Making coffee"), explain = "She was making coffee when she realised."), Exercise(id = "en-read-missing-keys-q2", kind = "written", prompt = "Where did the keys usually live?", options = listOf(), answers = listOf("in the blue bowl", "the blue bowl by the door", "the blue bowl"), explain = "They always lived in the blue bowl by the door."), Exercise(id = "en-read-missing-keys-q3", kind = "choice", prompt = "Who took the keys?", options = listOf("Diego's cat", "Diego", "A neighbour", "Nobody knows"), answers = listOf("Diego's cat"), explain = "Luna, the downstairs cat, collected small metal objects."), Exercise(id = "en-read-missing-keys-q4", kind = "written", prompt = "Name one other thing Luna had taken.", options = listOf(), answers = listOf("a bottle opener", "an earring", "last winter's missing earring", "three keys"), explain = "Three keys, a bottle opener and an earring."), Exercise(id = "en-read-missing-keys-q5", kind = "choice", prompt = "What was Marta's solution?", options = listOf("A hook high on the wall", "A new bowl", "A locked box", "She locked Luna out"), answers = listOf("A hook high on the wall"), explain = "She installed a hook high on the wall."), Exercise(id = "en-read-missing-keys-q6", kind = "choice", prompt = "Did Luna stop bringing gifts?", options = listOf("No — she kept bringing them", "Yes, immediately", "Yes, after a week", "The text doesn't say"), answers = listOf("No — she kept bringing them"), explain = "Luna, however, kept bringing gifts.")), skills = listOf("reading:detail", "grammar:past-continuous", "grammar:relative-clauses", "grammar:connectors", "function:tell-a-story")),
    ReadingText(id = "en-read-meetup-email", languageID = "en", title = "Planning the alumni meetup", level = "B1", topic = "plans", text = "Subject: Alumni meetup — your vote needed! Hi everyone, Great news: 34 of you answered the survey, so we're finally organising the spring meetup. The Terraza del Río, which most of you recommended, has availability on 14 or 21 June. If we choose the 14th, we'll have the terrace to ourselves but we'll have to finish by midnight. If we choose the 21st, it's shared with another group, although the music usually stops earlier. Several of you asked about a pre-dinner walk — if enough people arrive by 19:30, we'll do the river route first (about 40 minutes, flat and easy). Please vote by Friday. If fewer than twenty people vote, we'll postpone to September and I'll donate the deposit to the class fund! Looking forward to it, Bea", questions = listOf(Exercise(id = "en-read-meetup-email-q1", kind = "choice", prompt = "Which venue did most people recommend?", options = listOf("Terraza del Río", "The class fund", "The river route", "A shared hall"), answers = listOf("Terraza del Río"), explain = "The Terraza del Río, which most of you recommended."), Exercise(id = "en-read-meetup-email-q2", kind = "choice", prompt = "What is the downside of the 14th?", options = listOf("They must finish by midnight", "Another group shares it", "No terrace", "It's in September"), answers = listOf("They must finish by midnight"), explain = "On the 14th they have the terrace to themselves but finish by midnight."), Exercise(id = "en-read-meetup-email-q3", kind = "written", prompt = "What do they plan to do if enough people arrive by 19:30?", options = listOf(), answers = listOf("the river route", "do the river route first", "walk the river route"), explain = "They'll do the river route first."), Exercise(id = "en-read-meetup-email-q4", kind = "choice", prompt = "What happens if fewer than twenty people vote?", options = listOf("The meetup moves to September", "Bea chooses the date", "The venue decides", "Nothing"), answers = listOf("The meetup moves to September"), explain = "They'll postpone to September and donate the deposit."), Exercise(id = "en-read-meetup-email-q5", kind = "written", prompt = "How long is the river walk?", options = listOf(), answers = listOf("about 40 minutes", "40 minutes", "forty minutes"), explain = "About 40 minutes, flat and easy.")), skills = listOf("reading:detail", "grammar:first-conditional", "grammar:connectors", "writing:email")),
    ReadingText(id = "en-read-ai-emails-debate", languageID = "en", title = "Should AI write our emails?", level = "B2", topic = "work", text = "Last quarter, our company quietly enabled an AI assistant for all internal email. The results were measured, and they are worth reporting precisely. Response times improved by roughly a third, and — perhaps surprisingly — politeness increased: messages drafted by the assistant contain fewer blunt openings and more complete sentences. However, two problems are emerging. First, readers are starting to discount the politeness; when everyone sounds courteous, courtesy stops carrying information. Second, and more seriously, responsibility is blurring. When a wrong figure was sent to a client last month, three people said some version of 'the assistant wrote it.' The tool was not to blame, of course — the signature was. My position is therefore narrow but firm: let the assistant draft, but the name at the bottom owns every word. We are testing a one-line disclosure at the end of assisted emails, and if trust metrics hold, we will keep it. If they do not, we will rethink — in our own words.", questions = listOf(Exercise(id = "en-read-ai-emails-debate-q1", kind = "written", prompt = "By how much did response times improve?", options = listOf(), answers = listOf("roughly a third", "about a third", "a third"), explain = "Response times improved by roughly a third."), Exercise(id = "en-read-ai-emails-debate-q2", kind = "choice", prompt = "What surprising effect did the assistant have?", options = listOf("Politeness increased", "Emails got shorter", "People wrote less", "Costs fell"), answers = listOf("Politeness increased"), explain = "Messages contained fewer blunt openings and more complete sentences."), Exercise(id = "en-read-ai-emails-debate-q3", kind = "choice", prompt = "What happens when everyone sounds courteous?", options = listOf("Courtesy stops carrying information", "Emails get longer", "Nothing", "People write more"), answers = listOf("Courtesy stops carrying information"), explain = "Discounted politeness carries less meaning."), Exercise(id = "en-read-ai-emails-debate-q4", kind = "choice", prompt = "What is the author's firm position?", options = listOf("The signature owns every word", "Ban the assistant", "AI should write everything", "No disclosure needed"), answers = listOf("The signature owns every word"), explain = "Let it draft, but the name at the bottom owns every word."), Exercise(id = "en-read-ai-emails-debate-q5", kind = "written", prompt = "What will they do if trust metrics do not hold?", options = listOf(), answers = listOf("rethink", "they will rethink in their own words", "rethink the policy"), explain = "If they do not, they will rethink — in their own words.")), skills = listOf("reading:inference", "grammar:passive-intro", "grammar:connectors", "grammar:first-conditional", "writing:argument")),
    ReadingText(id = "en-read-market-report", languageID = "en", title = "Quarter in brief: the coffee market", level = "B2", topic = "business", text = "Summary for internal circulation — Q3. Prices rose considerably in the first half of the quarter, driven by weather rather than demand: the frost in July affected the two largest producing regions, which together account for roughly 55% of exports. Demand, by contrast, was flat. Supermarket own-brand lines were the least affected, arguably because their contracts are fixed annually; speciality roasters, which buy on the spot market, reported increases of up to forty per cent. It is widely believed that small cafés absorb such increases poorly, and our survey offers some support: 62% said they would rather reduce opening hours than raise the price of an espresso. Looking ahead, futures suggest a partial correction by December, although this depends on rainfall in August. We therefore recommend hedging half of Q4 volume now and reviewing the remainder in October. As ever, this report is a snapshot, not a guarantee.", questions = listOf(Exercise(id = "en-read-market-report-q1", kind = "choice", prompt = "What drove prices up?", options = listOf("Weather", "Demand", "New cafés", "Export taxes"), answers = listOf("Weather"), explain = "The July frost, not demand — demand was flat."), Exercise(id = "en-read-market-report-q2", kind = "written", prompt = "How much of exports do the two largest regions account for?", options = listOf(), answers = listOf("roughly 55%", "55%", "about 55 percent"), explain = "Roughly 55% of exports."), Exercise(id = "en-read-market-report-q3", kind = "choice", prompt = "Which buyers were least affected?", options = listOf("Supermarket own brands", "Speciality roasters", "Small cafés", "Futures traders"), answers = listOf("Supermarket own brands"), explain = "Arguably because their contracts are fixed annually."), Exercise(id = "en-read-market-report-q4", kind = "written", prompt = "What would 62% of small cafés rather do?", options = listOf(), answers = listOf("Reduce opening hours"), explain = "Rather than raise the price of an espresso."), Exercise(id = "en-read-market-report-q5", kind = "choice", prompt = "What does the report recommend for Q4?", options = listOf("Hedging half the volume now", "Waiting until December", "Buying nothing", "Raising prices by 40%"), answers = listOf("Hedging half the volume now"), explain = "Hedge half now, review the rest in October.")), skills = listOf("reading:inference", "grammar:passive-intro", "grammar:relative-clauses", "grammar:connectors", "function:express-opinion")),
    ReadingText(id = "en-read-op-ed-cities", languageID = "en", title = "Op-ed: the fifteen-minute fantasy", level = "C1", topic = "town", text = "The fifteen-minute city is, depending on who you ask, the future of urban life or a conspiracy with better branding. Strip away the noise, however, and the concept is almost disappointingly modest: housing, work, school and groceries within a short walk. That this modesty has been received as tyranny says less about urbanism than about the era in which it landed. Critics are right about one thing, though — proximity is a luxury good. The neighbourhoods that already deliver it are the most expensive in every city that measures, and a plan that paints a café on a map does not lower the rent. Arguably, then, the real fifteen-minute policy is not zoning but housing: build where people want to live, and the walk to the bakery takes care of itself. None of this makes the idea wrong. It makes it insufficient — which, in a field allergic to nuance, is already an unpopular position.", questions = listOf(Exercise(id = "en-read-op-ed-cities-q1", kind = "choice", prompt = "How does the author characterise the fifteen-minute city concept itself?", options = listOf("Almost disappointingly modest", "A conspiracy", "The future of urban life", "Tyranny"), answers = listOf("Almost disappointingly modest"), explain = "Strip away the noise and the concept is almost disappointingly modest."), Exercise(id = "en-read-op-ed-cities-q2", kind = "choice", prompt = "What do critics get right, according to the author?", options = listOf("Proximity is a luxury good", "Zoning is evil", "Cafés ruin cities", "Nothing"), answers = listOf("Proximity is a luxury good"), explain = "Critics are right about one thing: the neighbourhoods that deliver it are the most expensive."), Exercise(id = "en-read-op-ed-cities-q3", kind = "written", prompt = "What does the author call the real fifteen-minute policy?", options = listOf(), answers = listOf("housing", "build where people want to live"), explain = "Not zoning but housing: build where people want to live."), Exercise(id = "en-read-op-ed-cities-q4", kind = "written", prompt = "What is the author's final judgement of the idea?", options = listOf(), answers = listOf("insufficient, not wrong", "it makes the idea insufficient"), explain = "It makes the idea insufficient — which is already unpopular."), Exercise(id = "en-read-op-ed-cities-q5", kind = "choice", prompt = "What does 'a field allergic to nuance' imply?", options = listOf("Urbanism debates reject subtle positions", "Urbanists have allergies", "Cities cause allergies", "Nuance is common"), answers = listOf("Urbanism debates reject subtle positions"), explain = "Allergic to nuance = the field dislikes intermediate positions.")), skills = listOf("reading:inference", "grammar:connectors", "function:express-opinion", "writing:argument", "vocab:town")),
    ReadingText(id = "en-read-policy-memo", languageID = "en", title = "Internal memo: hybrid policy review", level = "C1", topic = "work", text = "MEMO — For internal circulation. Re: Hybrid working policy, phase two review. 1. Purpose. This memo summarises the findings of the phase-two review and sets out recommendations for the coming financial year. 2. Findings. Office attendance has averaged 2.3 days per week against a target of three, a shortfall attributable primarily to Wednesdays, which function in practice as a de facto remote day. Cross-team collaboration, as measured by shared project hours, has declined 12% year on year; within-team collaboration is unchanged. Exit interviews cite flexibility as the single most valued benefit (cited by 71% of leavers, compared with 34% for compensation). 3. Recommendations. It is recommended that: (a) Wednesday be designated a full on-site day with team-led programming; (b) the target be revised to an average, not a minimum; (c) the policy be reviewed again in twelve months. 4. Caveat. Attendance data was collected via badge swipes and may undercount presence in non-badged areas.", questions = listOf(Exercise(id = "en-read-policy-memo-q1", kind = "written", prompt = "What is the average office attendance against the target?", options = listOf(), answers = listOf("2.3 days per week against a target of three", "2.3 days", "2,3 days"), explain = "2.3 days per week against a target of three."), Exercise(id = "en-read-policy-memo-q2", kind = "choice", prompt = "What is the primary cause of the shortfall?", options = listOf("Wednesdays functioning as a remote day", "Bad weather", "The badge system", "Low pay"), answers = listOf("Wednesdays functioning as a remote day"), explain = "A shortfall attributable primarily to Wednesdays."), Exercise(id = "en-read-policy-memo-q3", kind = "choice", prompt = "What do exit interviews cite as the most valued benefit?", options = listOf("Flexibility", "Compensation", "Laptops", "Wednesdays"), answers = listOf("Flexibility"), explain = "Flexibility: 71% of leavers, compared with 34% for compensation."), Exercise(id = "en-read-policy-memo-q4", kind = "written", prompt = "Name one of the three recommendations.", options = listOf(), answers = listOf("wednesday be designated a full on-site day", "the target be revised to an average", "the policy be reviewed again in twelve months"), explain = "Any of (a), (b) or (c)."), Exercise(id = "en-read-policy-memo-q5", kind = "choice", prompt = "What caveat does the memo admit?", options = listOf("Badge data may undercount presence", "The survey was fake", "There is no data", "The target was met"), answers = listOf("Badge data may undercount presence"), explain = "Badge swipes miss non-badged areas.")), skills = listOf("reading:scan", "reading:detail", "grammar:passive-intro", "vocab:work", "writing:email")),
    ReadingText(id = "en-read-neighbourhood-blog", languageID = "en", title = "Neighbourhood notes: Maple Street", level = "A1", topic = "town", text = "Welcome to Maple Street! Our street is small but friendly. There is a bakery on the corner — the bread is very good. There are two schools and a small park with ten trees. There isn't a cinema, but the library is open on Saturdays. The chemist's is next to the park. Everything is near the bus stop. Our neighbours are friendly and quiet. On Saturdays there is a small market with fruit and flowers. Come and visit!", questions = listOf(Exercise(id = "en-read-neighbourhood-blog-q1", kind = "choice", prompt = "What is on the corner?", options = listOf("A bakery", "A cinema", "A school", "A market"), answers = listOf("A bakery"), explain = "There is a bakery on the corner."), Exercise(id = "en-read-neighbourhood-blog-q2", kind = "written", prompt = "How many trees are in the park?", options = listOf(), answers = listOf("ten", "10"), explain = "A small park with ten trees."), Exercise(id = "en-read-neighbourhood-blog-q3", kind = "choice", prompt = "When is the library open?", options = listOf("On Saturdays", "Every day", "Never", "On Sundays"), answers = listOf("On Saturdays"), explain = "The library is open on Saturdays."), Exercise(id = "en-read-neighbourhood-blog-q4", kind = "choice", prompt = "Where is the chemist's?", options = listOf("Next to the park", "On the corner", "Near the school", "Far away"), answers = listOf("Next to the park"), explain = "The chemist's is next to the park."), Exercise(id = "en-read-neighbourhood-blog-q5", kind = "choice", prompt = "What is there on Saturdays?", options = listOf("A small market", "A cinema", "A party", "Nothing"), answers = listOf("A small market"), explain = "Fruit and flowers — the Saturday market.")), skills = listOf("vocab:town", "grammar:there-is-are", "reading:detail", "function:ask-simple-questions")),
    ReadingText(id = "en-read-tuscany-note", languageID = "en", title = "A very short travel story", level = "B1", topic = "travel", text = "The lock wouldn't turn. That was the first sign. My Airbnb host had sent four codes for one door, and none of them worked. It was 30 degrees, my phone had 4% battery, and a man with a dog was watching me from a window. I typed a message to the host: 'I'm outside, the codes don't work.' Three dots. Nothing. Ten minutes later the dog man opened the door downstairs. 'You must be the Tuscany guest,' he said, in perfect English. 'My daughter manages the flat. Come up, have some water.' By the time I got inside, we had laughed about the codes twice, and he had given me two plums from his tree. Some arrivals are better than the photos.", questions = listOf(Exercise(id = "en-read-tuscany-note-q1", kind = "choice", prompt = "What is the first sign of trouble?", options = listOf("The lock wouldn't turn", "The host's message", "The dog", "The heat"), answers = listOf("The lock wouldn't turn"), explain = "Open in the middle: the lock wouldn't turn."), Exercise(id = "en-read-tuscany-note-q2", kind = "written", prompt = "How many codes did the host send?", options = listOf(), answers = listOf("four", "4"), explain = "Four codes for one door."), Exercise(id = "en-read-tuscany-note-q3", kind = "choice", prompt = "What was the phone's battery?", options = listOf("4%", "40%", "Full", "Dead"), answers = listOf("4%"), explain = "My phone had 4% battery."), Exercise(id = "en-read-tuscany-note-q4", kind = "written", prompt = "What did the dog man give the guest?", options = listOf(), answers = listOf("two plums", "plums", "some plums"), explain = "Two plums from his tree."), Exercise(id = "en-read-tuscany-note-q5", kind = "choice", prompt = "What is the closing thought?", options = listOf("Some arrivals are better than the photos", "Never use Airbnb", "Tuscany is far", "Dogs are friendly"), answers = listOf("Some arrivals are better than the photos"), explain = "One line, reflective, light.")), skills = listOf("reading:inference", "grammar:past-continuous", "function:tell-a-story", "grammar:connectors", "writing:story")),
    ReadingText(id = "en-read-opinion-ai-art", languageID = "en", title = "Opinion: AI art is still art", level = "B2", topic = "work", text = "The argument against AI art is always the same: a machine cannot feel, therefore it cannot create. But this argument proves too much. If feeling is the requirement, then we must also reject photography (the camera does not feel), digital painting (the software does not feel) and, arguably, most commissioned work (the painter does not always feel either). What matters is not the tool but the intention behind it. A person who writes a prompt, curates the output, revises, and presents the result is making choices. Those choices may be good or bad — that is a separate question. But they are choices, and choices are the raw material of art. The real threat is not AI art; it is the flood of mediocre AI art that drowns the genuinely interesting work. The solution is curation, not prohibition.", questions = listOf(Exercise(id = "en-read-opinion-ai-art-q1", kind = "choice", prompt = "What is the standard argument against AI art?", options = listOf("A machine cannot feel, so it cannot create", "AI art is too expensive", "AI art is too fast", "Nobody likes it"), answers = listOf("A machine cannot feel, so it cannot create"), explain = "A machine cannot feel, therefore it cannot create."), Exercise(id = "en-read-opinion-ai-art-q2", kind = "choice", prompt = "What does the author say the argument proves too much?", options = listOf("It would also reject photography and digital painting", "It proves AI is bad", "It proves artists are wrong", "Nothing"), answers = listOf("It would also reject photography and digital painting"), explain = "The camera doesn't feel either."), Exercise(id = "en-read-opinion-ai-art-q3", kind = "written", prompt = "What matters more than the tool?", options = listOf(), answers = listOf("the intention behind it"), explain = "What matters is the intention, not the tool."), Exercise(id = "en-read-opinion-ai-art-q4", kind = "written", prompt = "What are the raw material of art?", options = listOf(), answers = listOf("choices"), explain = "Choices are the raw material of art."), Exercise(id = "en-read-opinion-ai-art-q5", kind = "choice", prompt = "What is the real threat?", options = listOf("The flood of mediocre AI art", "AI art itself", "Prohibition", "Traditional artists"), answers = listOf("The flood of mediocre AI art"), explain = "The flood drowns the genuinely interesting work."), Exercise(id = "en-read-opinion-ai-art-q6", kind = "choice", prompt = "What solution does the author propose?", options = listOf("Curation, not prohibition", "Banning AI art", "More AI art", "Higher prices"), answers = listOf("Curation, not prohibition"), explain = "Curation, not prohibition.")), skills = listOf("reading:inference", "grammar:connectors", "function:express-opinion", "writing:argument", "grammar:passive-intro")),
    ReadingText(id = "en-read-policy-report", languageID = "en", title = "Policy report: libraries in the digital age", level = "C1", topic = "work", text = "1. Scope. This report examines the role of public libraries in municipalities with populations exceeding 50,000, drawing on data from 340 institutions across 12 countries collected between 2022 and 2025. 2. Principal findings. Contrary to widespread assumptions, circulation of physical books has declined by only 8% since 2022, while attendance at non-book events (workshops, language exchanges, coding clubs) has increased by 210% over the same period. Libraries that rebranded as 'community hubs' saw a 34% increase in first-time visitors; those that maintained a traditional focus saw a 14% decrease. It should be noted, however, that the rebranding group also received 40% more funding on average, making causality difficult to establish. 3. Limitations. The data excludes rural libraries and does not distinguish between scheduled and walk-in attendance. 4. Recommendation. Municipalities should fund libraries as social infrastructure rather than as book warehouses, and should commission a follow-up study with better attendance methodology.", questions = listOf(Exercise(id = "en-read-policy-report-q1", kind = "choice", prompt = "How much has physical book circulation declined?", options = listOf("8% since 2022", "80% since 2022", "It has increased", "It has not changed"), answers = listOf("8% since 2022"), explain = "Contrary to assumptions, only 8% decline."), Exercise(id = "en-read-policy-report-q2", kind = "written", prompt = "By how much have non-book events increased?", options = listOf(), answers = listOf("210%"), explain = "Attendance at non-book events has increased by 210%."), Exercise(id = "en-read-policy-report-q3", kind = "choice", prompt = "What happened to libraries that rebranded as community hubs?", options = listOf("34% more first-time visitors", "34% fewer visitors", "No change", "They closed"), answers = listOf("34% more first-time visitors"), explain = "A 34% increase in first-time visitors."), Exercise(id = "en-read-policy-report-q4", kind = "choice", prompt = "What limitation does the report admit?", options = listOf("Rebranding libraries received 40% more funding", "The data is fake", "Libraries refused to participate", "No limitation"), answers = listOf("Rebranding libraries received 40% more funding"), explain = "More funding makes causality difficult to establish."), Exercise(id = "en-read-policy-report-q5", kind = "choice", prompt = "What does the report recommend?", options = listOf("Fund libraries as social infrastructure", "Close libraries", "Buy more books", "Stop funding"), answers = listOf("Fund libraries as social infrastructure"), explain = "Fund as social infrastructure, not book warehouses."), Exercise(id = "en-read-policy-report-q6", kind = "written", prompt = "What data does the report exclude?", options = listOf(), answers = listOf("rural libraries"), explain = "The data excludes rural libraries.")), skills = listOf("reading:inference", "reading:scan", "grammar:passive-intro", "grammar:connectors", "writing:argument")),
    ReadingText(id = "es-read-grupo-caminata", languageID = "es", title = "El grupo de caminata", level = "A1", topic = "salud", unitID = "es-foundations-u2", text = "Los martes, el barrio organiza una caminata gratis. Empieza a las nueve en la plaza y termina en el río. El grupo es mixto: hay estudiantes, familias y jubilados. Nadie corre; la idea es caminar y hablar. Al final, los que quieren desayunan juntos en un bar del mercado. Marta va desde hace un mes y ya tiene tres amigos nuevos. Dice que es la hora más tranquila de su semana.", questions = listOf(Exercise(id = "es-read-grupo-caminata-q1", kind = "choice", prompt = "¿Cuándo es la caminata?", options = listOf("Los martes", "Los lunes", "Los sábados", "Todos los días"), answers = listOf("Los martes"), explain = "Los martes, el barrio organiza una caminata gratis."), Exercise(id = "es-read-grupo-caminata-q2", kind = "written", prompt = "¿A qué hora empieza?", options = listOf(), answers = listOf("a las nueve", "las nueve", "nueve"), explain = "Empieza a las nueve en la plaza."), Exercise(id = "es-read-grupo-caminata-q3", kind = "choice", prompt = "¿Quién va al grupo?", options = listOf("Estudiantes, familias y jubilados", "Solo estudiantes", "Solo jubilados", "Solo familias"), answers = listOf("Estudiantes, familias y jubilados"), explain = "El grupo es mixto."), Exercise(id = "es-read-grupo-caminata-q4", kind = "choice", prompt = "¿Qué hacen al final los que quieren?", options = listOf("Desayunan juntos", "Corren al río", "Vuelven a casa", "Toman el autobús"), answers = listOf("Desayunan juntos"), explain = "Desayunan juntos en un bar del mercado."), Exercise(id = "es-read-grupo-caminata-q5", kind = "written", prompt = "¿Cuánto tiempo lleva Marta?", options = listOf(), answers = listOf("un mes", "1 mes"), explain = "Marta va desde hace un mes.")), skills = listOf("reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine")),
    ReadingText(id = "es-read-piso-luz", languageID = "es", title = "El anuncio del piso", level = "A2", topic = "pisos", unitID = "es-foundations-u7", text = "Piso luminoso de dos habitaciones en alquiler desde septiembre. Está en la tercera planta, con ascensor, y tiene un balcón que da al patio, así que es tranquilo. El salón es más grande que la cocina, pero la cocina tiene ventana. El barrio tiene mercado los sábados y la parada del metro está a cinco minutos. No es el más barato de la zona, pero es el mejor iluminado. Se pide un mes de fianza y se prefiere a alguien que trabaje desde casa, como los dueños actuales.", questions = listOf(Exercise(id = "es-read-piso-luz-q1", kind = "choice", prompt = "¿Cuándo está disponible?", options = listOf("Desde septiembre", "Desde agosto", "Ahora mismo", "En enero"), answers = listOf("Desde septiembre"), explain = "En alquiler desde septiembre."), Exercise(id = "es-read-piso-luz-q2", kind = "choice", prompt = "¿Por qué es tranquilo?", options = listOf("Da al patio", "Está en la planta baja", "No tiene vecinos", "Está en el campo"), answers = listOf("Da al patio"), explain = "El balcón da al patio, así que es tranquilo."), Exercise(id = "es-read-piso-luz-q3", kind = "written", prompt = "¿A cuántos minutos está el metro?", options = listOf(), answers = listOf("cinco minutos", "5 minutos", "cinco"), explain = "La parada del metro está a cinco minutos."), Exercise(id = "es-read-piso-luz-q4", kind = "choice", prompt = "¿Cómo es comparado con la zona?", options = listOf("No es el más barato, pero sí el mejor iluminado", "Es el más barato", "Es el peor iluminado", "Es el más pequeño"), answers = listOf("No es el más barato, pero sí el mejor iluminado"), explain = "No es el más barato de la zona, pero es el mejor iluminado."), Exercise(id = "es-read-piso-luz-q5", kind = "choice", prompt = "¿A quién prefieren los dueños?", options = listOf("A alguien que trabaje desde casa", "A estudiantes", "A familias con niños", "A jubilados"), answers = listOf("A alguien que trabaje desde casa"), explain = "Se prefiere a alguien que trabaje desde casa.")), skills = listOf("reading:detail", "reading:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ReadingText(id = "es-read-viaje-inolvidable", languageID = "es", title = "El viaje inolvidable", level = "B1", topic = "viajes", unitID = "es-foundations-u5", text = "El verano pasado hice el viaje que más había soñado: quince días en Perú. Ya había visitado México y Argentina, pero Sudamérica todavía me sorprendió. El tercer día subí al Machu Picchu. Había niebla, así que al principio no se veía nada. Después, poco a poco, salió el sol y apareció la ciudad entera. No dije nada; me quedé mirando. Conocí a una familia de Cusco en el tren de vuelta, y me invitaron a cenar. «Los viajeros siempre dicen lo mismo», se rió la abuela, «pero esta sopa es de verdad». Tenía razón: fue la mejor cena del viaje. Desde entonces, cada vez que alguien pregunta por un destino, yo digo Perú.", questions = listOf(Exercise(id = "es-read-viaje-inolvidable-q1", kind = "choice", prompt = "¿Cuánto duró el viaje?", options = listOf("Quince días", "Diez días", "Un mes", "Tres días"), answers = listOf("Quince días"), explain = "Quince días en Perú."), Exercise(id = "es-read-viaje-inolvidable-q2", kind = "written", prompt = "¿Qué países había visitado antes?", options = listOf(), answers = listOf("mexico y argentina", "méxico y argentina"), explain = "Ya había visitado México y Argentina."), Exercise(id = "es-read-viaje-inolvidable-q3", kind = "choice", prompt = "¿Por qué no se veía nada al principio?", options = listOf("Había niebla", "Estaba cerrado", "Llovía mucho", "Era de noche"), answers = listOf("Había niebla"), explain = "Había niebla, así que al principio no se veía nada."), Exercise(id = "es-read-viaje-inolvidable-q4", kind = "choice", prompt = "¿Con quién cenó el narrador?", options = listOf("Con una familia de Cusco", "Con la abuela del hotel", "Solo", "Con amigos del tren"), answers = listOf("Con una familia de Cusco"), explain = "Conocí a una familia de Cusco y me invitaron a cenar."), Exercise(id = "es-read-viaje-inolvidable-q5", kind = "written", prompt = "¿Qué dice ahora cuando le preguntan por un destino?", options = listOf(), answers = listOf("peru", "perú", "yo digo peru", "digo peru"), explain = "Cada vez que alguien pregunta, yo digo Perú.")), skills = listOf("reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel")),
    ReadingText(id = "es-read-columna-peatonal", languageID = "es", title = "Columna: peatonalicemos", level = "B2", topic = "opinión", unitID = "es-foundations-u9", text = "Creo que deberíamos peatonalizar el centro. Por un lado, bajaría el ruido: los vecinos de la plaza llevan años pidiendo silencio. Por otro lado, bajaría la contaminación, que ya supera los límites legales. Es cierto que el comercio teme perder clientes, pero los datos de otras ciudades dicen lo contrario: donde el coche desaparece, la gente camina más y compra más. La empresa cuyo informe publicaron el mes pasado calculó un 15 % más de ventas en calles sin tráfico. Por todo ello, defiendo la medida: si tuviéramos el valor de probarlo un año, no querríamos volver atrás.", questions = listOf(Exercise(id = "es-read-columna-peatonal-q1", kind = "choice", prompt = "¿Cuál es la tesis de la columna ?", options = listOf("Peatonalizar el centro", "Ampliar la autopista", "Prohibir bicis", "Construir un parking"), answers = listOf("Peatonalizar el centro"), explain = "« Creo que deberíamos peatonalizar el centro »."), Exercise(id = "es-read-columna-peatonal-q2", kind = "written", prompt = "¿Qué supera los límites legales ?", options = listOf(), answers = listOf("la contaminacion", "la contaminación"), explain = "La contaminación ya supera los límites legales."), Exercise(id = "es-read-columna-peatonal-q3", kind = "choice", prompt = "¿Qué teme el comercio ?", options = listOf("Perder clientes", "Pagar más impuestos", "Cerrar en verano", "Mudar de ciudad"), answers = listOf("Perder clientes"), explain = "El comercio teme perder clientes."), Exercise(id = "es-read-columna-peatonal-q4", kind = "written", prompt = "¿Cuánto más venderían las calles sin tráfico ?", options = listOf(), answers = listOf("15%", "un 15%", "quince por ciento", "15 por ciento"), explain = "Un 15 % más de ventas."), Exercise(id = "es-read-columna-peatonal-q5", kind = "choice", prompt = "¿Qué propone la autora al final ?", options = listOf("Probarlo un año", "Olvidar el plan", "Multar más", "Votar de nuevo"), answers = listOf("Probarlo un año"), explain = "« Si tuviéramos el valor de probarlo un año ».")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional")),
    ReadingText(id = "es-read-ensayo-ciudad", languageID = "es", title = "La ciudad de quince minutos", level = "C1", topic = "opinión", unitID = "es-foundations-u10", text = "La ciudad de los quince minutos es, por así decirlo, una promesa modesta: nada de coches voladores, solo vida cercana. Para empezar, acercar los servicios reduce el desplazamiento obligatorio; en segundo lugar, la calle recupera su papel de lugar de encuentro. No obstante, el ensayo tiene un punto ciego: quien no puede pagarse un piso en el centro queda fuera del mapa. Desde mi punto de vista, la medida solo funciona si va acompañada de vivienda asequible; de lo contrario, es un lujo con lema. Por otra parte, no todo es economía: hay vecindarios que ya viven a escala humana sin haberlo planeado. En resumen, merece la pena intentarlo, siempre que la palabra clave no sea « minutos », sino « vecindario ».", questions = listOf(Exercise(id = "es-read-ensayo-ciudad-q1", kind = "choice", prompt = "¿Qué riesgo ve el autor en la medida ?", options = listOf("Que puede volverse un lujo", "Que promete coches voladores", "Que es demasiado modesta", "Que odia los minutos"), answers = listOf("Que puede volverse un lujo"), explain = "Sin vivienda asequible, « es un lujo con lema »."), Exercise(id = "es-read-ensayo-ciudad-q2", kind = "written", prompt = "¿Qué necesita la medida para funcionar, según el autor ?", options = listOf(), answers = listOf("vivienda asequible", "la vivienda asequible"), explain = "« Solo funciona si va acompañada de vivienda asequible »."), Exercise(id = "es-read-ensayo-ciudad-q3", kind = "choice", prompt = "¿Cuál es la palabra clave final del ensayo ?", options = listOf("Vecindario", "Minutos", "Lema", "Mapa"), answers = listOf("Vecindario"), explain = "« No sea 'minutos', sino 'vecindario' »."), Exercise(id = "es-read-ensayo-ciudad-q4", kind = "choice", prompt = "¿Qué ejemplo da de vida ya a escala humana ?", options = listOf("Vecindarios no planificados", "El centro pagado", "Los coches voladores", "El desplazamiento obligatorio"), answers = listOf("Vecindarios no planificados"), explain = "« Hay vecindarios que ya viven a escala humana sin haberlo planeado »."), Exercise(id = "es-read-ensayo-ciudad-q5", kind = "written", prompt = "¿Cómo califica el autor la promesa de los quince minutos ?", options = listOf(), answers = listOf("modesta", "una promesa modesta", "promesa modesta"), explain = "« Una promesa modesta », dice desde el principio.")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations")),
    ReadingText(id = "es-read-carta-directiva", languageID = "es", title = "Carta de la dirección", level = "C1", topic = "empresa", unitID = "es-foundations-u10", text = "Estimado equipo: les escribimos para compartir la reorganización del próximo trimestre. Para empezar, agradecerles el esfuerzo del último ciclo: los indicadores han mejorado notablemente. No obstante, el contexto exige ajustes. En primer lugar, consolidaremos los dos departamentos comerciales en una sola dirección; en segundo lugar, el trabajo en remoto quedará limitado a dos días semanales, salvo acuerdo contrario con el responsable de cada área. Somos conscientes de que, en cierto modo, la medida reduce la autonomía ganada; por otra parte, evita una reducción de plantilla, que era la alternativa sobre la mesa. Les convocamos a una asamblea el jueves a las once para responder a sus preguntas. Quedamos a su disposición. La dirección.", questions = listOf(Exercise(id = "es-read-carta-directiva-q1", kind = "choice", prompt = "¿Qué cambia en el trabajo en remoto ?", options = listOf("Dos días semanales como máximo", "Se prohibe del todo", "Pasa a ser obligatorio cinco días", "Depende de cada ministerio"), answers = listOf("Dos días semanales como máximo"), explain = "« Quedará limitado a dos días semanales »."), Exercise(id = "es-read-carta-directiva-q2", kind = "choice", prompt = "¿Qué evita la dirección con la medida ?", options = listOf("Una reducción de plantilla", "Una asamblea el jueves", "La flexibilidad semanal", "Los indicadores del ciclo"), answers = listOf("Una reducción de plantilla"), explain = "« Por otra parte, evita una reducción de plantilla »."), Exercise(id = "es-read-carta-directiva-q3", kind = "written", prompt = "¿Cuándo convoca la dirección a la asamblea ?", options = listOf(), answers = listOf("el jueves a las once", "jueves a las once", "el jueves"), explain = "Les convocan el jueves a las once."), Exercise(id = "es-read-carta-directiva-q4", kind = "choice", prompt = "¿Qué reconoce la dirección sobre la medida ?", options = listOf("Que reduce la autonomía en cierto modo", "Que sube los indicadores", "Que crea dos direcciones nuevas", "Que no hace falta ninguna medida"), answers = listOf("Que reduce la autonomía en cierto modo"), explain = "« Somos conscientes de que, en cierto modo, reduce la autonomía ganada »."), Exercise(id = "es-read-carta-directiva-q5", kind = "written", prompt = "¿Quién firma la carta ?", options = listOf(), answers = listOf("la direccion", "la dirección"), explain = "Firma « La dirección ».")), skills = listOf("reading:detail", "reading:scan", "vocab:work", "grammar:connectors")),
    ReadingText(id = "es-read-resena-critica", languageID = "es", title = "Reseña: la exposición « Umbral »", level = "C1", topic = "cultura", unitID = "es-foundations-u10", text = "Con « Umbral », la galería Lagarta intenta lo difícil: una exposición sobre el silencio. Para empezar, acierta con el recorrido: de la entrada al fondo, cada sala baja el volumen, y el visitante baja la voz sin que nadie se lo pida. La pieza central — cien radios encendidos que no emiten nada — es, por así decirlo, el ruido hecho ausencia. No obstante, la muestra adolece de pretensión: los carteles explican lo que las obras ya dicen, y lo dicen mejor. Desde mi punto de vista, sobra la mitad de los textos. A esto se añade que el catálogo, carísimo, retoca las fotografías hasta vaciarlas. En resumen: vaya, y pronto; la exposición se sostiene sola, a pesar de quienes la acompañan.", questions = listOf(Exercise(id = "es-read-resena-critica-q1", kind = "choice", prompt = "¿Qué opina la crítica de los carteles explicativos ?", options = listOf("Que sobran en parte", "Que son imprescindibles", "Que deberían ampliarse", "Que son demasiado baratos"), answers = listOf("Que sobran en parte"), explain = "« Sobra la mitad de los textos: las obras lo dicen mejor »."), Exercise(id = "es-read-resena-critica-q2", kind = "choice", prompt = "¿Qué es la pieza central de la muestra ?", options = listOf("Cien radios encendidos y mudos", "Una sala a oscuras", "Un catálogo carísimo", "Un cartel explicativo"), answers = listOf("Cien radios encendidos y mudos"), explain = "« Cien radios encendidos que no emiten nada »."), Exercise(id = "es-read-resena-critica-q3", kind = "written", prompt = "¿Cómo describe la crítica el intento de la galería ?", options = listOf(), answers = listOf("dificil", "difícil", "un intento dificil", "un intento difícil"), explain = "« Intenta lo difícil: una exposición sobre el silencio »."), Exercise(id = "es-read-resena-critica-q4", kind = "choice", prompt = "¿Qué se deduce sobre el visitante ?", options = listOf("Que respeta el silencio sin que se lo pidan", "Que habla durante todo el recorrido", "Que se queja del precio del catálogo", "Que entra y sale enseguida"), answers = listOf("Que respeta el silencio sin que se lo pidan"), explain = "« Baja la voz sin que nadie se lo pida »."), Exercise(id = "es-read-resena-critica-q5", kind = "written", prompt = "¿Qué defecto señala la crítica del catálogo ?", options = listOf(), answers = listOf("retoca las fotografias", "retoca las fotografías", "retoca las fotos"), explain = "Retoca las fotografías hasta vaciarlas; además, es carísimo.")), skills = listOf("reading:inference", "function:express-opinion", "grammar:connectors", "vocab:collocations")),
    ReadingText(id = "es-read-anuncio-companero", languageID = "es", title = "Se busca compañera de piso", level = "A1", topic = "vivienda", unitID = "es-foundations-u11", text = "Busco una compañera de piso para un piso en la calle Serrano. El piso tiene tres habitaciones y dos baños. Tu habitación es grande, con una ventana y una mesa. Mi habitación está al lado del salón. En la cocina hay una lavadora nueva. El alquiler es de 350 euros al mes, más la luz y el agua. Busco una persona tranquila y ordenada. Mi nombre es Elena y trabajo en un hospital. ¿Estás interesada? Llama al 602 123 405.", questions = listOf(Exercise(id = "es-read-anuncio-companero-q1", kind = "choice", prompt = "¿Cuántas habitaciones tiene el piso?", options = listOf("Tres", "Dos", "Cuatro", "Una"), answers = listOf("Tres"), explain = "El piso tiene tres habitaciones y dos baños."), Exercise(id = "es-read-anuncio-companero-q2", kind = "written", prompt = "¿Cómo es la habitación del anuncio?", options = listOf(), answers = listOf("grande", "es grande", "muy grande"), explain = "Tu habitación es grande, con una ventana y una mesa."), Exercise(id = "es-read-anuncio-companero-q3", kind = "choice", prompt = "¿Dónde está la habitación de Elena?", options = listOf("Al lado del salón", "Encima de la cocina", "Debajo de la escalera", "Lejos del baño"), answers = listOf("Al lado del salón"), explain = "Mi habitación está al lado del salón."), Exercise(id = "es-read-anuncio-companero-q4", kind = "written", prompt = "¿Cuánto es el alquiler al mes?", options = listOf(), answers = listOf("350 euros", "trescientos cincuenta euros", "350"), explain = "El alquiler es de 350 euros al mes."), Exercise(id = "es-read-anuncio-companero-q5", kind = "choice", prompt = "¿Qué persona busca Elena?", options = listOf("Tranquila y ordenada", "Simpática y ruidosa", "Joven y deportista", "Seria y callada"), answers = listOf("Tranquila y ordenada"), explain = "Busco una persona tranquila y ordenada.")), skills = listOf("reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people")),
    ReadingText(id = "es-read-mensaje-grupo", languageID = "es", title = "Mensajes del grupo", level = "A1", topic = "planes", unitID = "es-foundations-u14", text = "Marta: ¡Chicos! El sábado hace sol. ¿Jugamos al tenis en el parque?\nPablo: Me encanta el tenis. Siempre juego los sábados.\nAna: Yo a veces juego, pero el sábado trabajo por la mañana. ¿Y el domingo?\nMarta: El domingo perfecto. Yo siempre nado por la mañana, pero por la tarde estoy libre.\nPablo: Yo nunca trabajo los domingos. ¿Quedamos a las cinco?\nAna: Vale, a las cinco. Yo llevo el café.\nMarta: ¡Perfecto! Nos vemos el domingo a las cinco.", questions = listOf(Exercise(id = "es-read-mensaje-grupo-q1", kind = "choice", prompt = "¿Qué día hace sol?", options = listOf("El sábado", "El domingo", "El lunes", "El viernes"), answers = listOf("El sábado"), explain = "Marta escribe: el sábado hace sol."), Exercise(id = "es-read-mensaje-grupo-q2", kind = "choice", prompt = "¿Quién siempre juega al tenis los sábados?", options = listOf("Pablo", "Ana", "Marta", "Nadie"), answers = listOf("Pablo"), explain = "Pablo: siempre juego los sábados."), Exercise(id = "es-read-mensaje-grupo-q3", kind = "written", prompt = "¿Qué hace siempre Marta por la mañana?", options = listOf(), answers = listOf("Nada", "nada", "nado"), explain = "Yo siempre nado por la mañana, dice Marta."), Exercise(id = "es-read-mensaje-grupo-q4", kind = "choice", prompt = "¿Quién nunca trabaja los domingos?", options = listOf("Pablo", "Ana", "Marta", "Todos"), answers = listOf("Pablo"), explain = "Pablo nunca trabaja los domingos."), Exercise(id = "es-read-mensaje-grupo-q5", kind = "written", prompt = "¿A qué hora quedan el domingo?", options = listOf(), answers = listOf("A las cinco", "a las cinco", "las cinco"), explain = "Quedamos a las cinco."), Exercise(id = "es-read-mensaje-grupo-q6", kind = "choice", prompt = "¿Qué lleva Ana?", options = listOf("El café", "El tenis", "La toalla", "El agua"), answers = listOf("El café"), explain = "Yo llevo el café, dice Ana.")), skills = listOf("reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs")),
    ReadingText(id = "fr-read-groupe-marche", languageID = "fr", title = "Le groupe de marche", level = "A1", topic = "santé", unitID = "fr-foundations-u2", text = "Les mardis, le quartier organise une marche gratuite. Elle commence à neuf heures sur la place et finit au bord du fleuve. Le groupe est mixte : il y a des étudiants, des familles et des retraités. Personne ne court ; l'idée, c'est marcher et parler. À la fin, ceux qui veulent prennent le petit-déjeuner ensemble dans un bar du marché. Camille y va depuis un mois et elle a déjà trois nouveaux amis. Elle dit que c'est le moment le plus tranquille de sa semaine.", questions = listOf(Exercise(id = "fr-read-groupe-marche-q1", kind = "choice", prompt = "Quand a lieu la marche ?", options = listOf("Les mardis", "Les lundis", "Les samedis", "Tous les jours"), answers = listOf("Les mardis"), explain = "Les mardis, le quartier organise une marche gratuite."), Exercise(id = "fr-read-groupe-marche-q2", kind = "written", prompt = "À quelle heure commence-t-elle ?", options = listOf(), answers = listOf("a neuf heures", "à neuf heures", "neuf heures"), explain = "Elle commence à neuf heures sur la place."), Exercise(id = "fr-read-groupe-marche-q3", kind = "choice", prompt = "Qui participe ?", options = listOf("Étudiants, familles et retraités", "Seulement des étudiants", "Seulement des retraités", "Seulement des familles"), answers = listOf("Étudiants, familles et retraités"), explain = "Le groupe est mixte."), Exercise(id = "fr-read-groupe-marche-q4", kind = "choice", prompt = "Que font ceux qui veulent à la fin ?", options = listOf("Ils prennent le petit-déjeuner ensemble", "Ils courent au fleuve", "Ils rentrent chez eux", "Ils prennent le bus"), answers = listOf("Ils prennent le petit-déjeuner ensemble"), explain = "Petit-déjeuner ensemble dans un bar du marché."), Exercise(id = "fr-read-groupe-marche-q5", kind = "written", prompt = "Depuis combien de temps Camille y va-t-elle ?", options = listOf(), answers = listOf("un mois", "1 mois"), explain = "Camille y va depuis un mois.")), skills = listOf("reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine")),
    ReadingText(id = "fr-read-annonce-appart", languageID = "fr", title = "L'annonce de l'appartement", level = "A2", topic = "appartements", unitID = "fr-foundations-u4", text = "Appartement lumineux de deux chambres à louer à partir de septembre. Il est au troisième étage, avec ascenseur, et il a un balcon qui donne sur la cour, donc il est calme. Le salon est plus grand que la cuisine, mais la cuisine a une fenêtre. Le quartier a un marché le samedi et la station de métro est à cinq minutes. Ce n'est pas le moins cher du quartier, mais c'est le mieux éclairé. Un mois de caution est demandé, et on préfère quelqu'un qui travaille à la maison, comme les propriétaires actuels.", questions = listOf(Exercise(id = "fr-read-annonce-appart-q1", kind = "choice", prompt = "Quand est-il disponible ?", options = listOf("À partir de septembre", "À partir d'août", "Tout de suite", "En janvier"), answers = listOf("À partir de septembre"), explain = "À louer à partir de septembre."), Exercise(id = "fr-read-annonce-appart-q2", kind = "choice", prompt = "Pourquoi est-il calme ?", options = listOf("Il donne sur la cour", "Il est au rez-de-chaussée", "Il n'a pas de voisins", "Il est à la campagne"), answers = listOf("Il donne sur la cour"), explain = "Le balcon donne sur la cour, donc il est calme."), Exercise(id = "fr-read-annonce-appart-q3", kind = "written", prompt = "À combien de minutes est le métro ?", options = listOf(), answers = listOf("cinq minutes", "5 minutes", "cinq"), explain = "La station de métro est à cinq minutes."), Exercise(id = "fr-read-annonce-appart-q4", kind = "choice", prompt = "Comment est-il comparé au quartier ?", options = listOf("Pas le moins cher, mais le mieux éclairé", "Le moins cher", "Le moins éclairé", "Le plus petit"), answers = listOf("Pas le moins cher, mais le mieux éclairé"), explain = "Pas le moins cher, mais le mieux éclairé."), Exercise(id = "fr-read-annonce-appart-q5", kind = "choice", prompt = "Qui préfèrent les propriétaires ?", options = listOf("Quelqu'un qui travaille à la maison", "Des étudiants", "Des familles avec enfants", "Des retraités"), answers = listOf("Quelqu'un qui travaille à la maison"), explain = "On préfère quelqu'un qui travaille à la maison.")), skills = listOf("reading:detail", "reading:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ReadingText(id = "fr-read-voyage-inoubliable", languageID = "fr", title = "Le voyage inoubliable", level = "B1", topic = "voyages", unitID = "fr-foundations-u6", text = "L'été dernier, j'ai fait le voyage dont j'avais le plus rêvé : quinze jours au Pérou. J'avais déjà visité le Mexique et l'Argentine, mais l'Amérique du Sud m'a encore surpris. Le troisième jour, je suis monté au Machu Picchu. Il y avait du brouillard, donc au début on ne voyait rien. Puis, peu à peu, le soleil est sorti et la ville entière est apparue. Je n'ai rien dit ; je suis resté à regarder. Dans le train du retour, j'ai rencontré une famille de Cusco, et ils m'ont invité à dîner. « Les voyageurs disent toujours la même chose », a ri la grand-mère, « mais cette soupe est vraie ». Elle avait raison : c'était le meilleur dîner du voyage. Depuis, chaque fois qu'on me demande une destination, je réponds le Pérou.", questions = listOf(Exercise(id = "fr-read-voyage-inoubliable-q1", kind = "choice", prompt = "Combien de temps a duré le voyage ?", options = listOf("Quinze jours", "Dix jours", "Un mois", "Trois jours"), answers = listOf("Quinze jours"), explain = "Quinze jours au Pérou."), Exercise(id = "fr-read-voyage-inoubliable-q2", kind = "written", prompt = "Quels pays avait-il déjà visités ?", options = listOf(), answers = listOf("mexique et argentine", "le mexique et l'argentine"), explain = "J'avais déjà visité le Mexique et l'Argentine."), Exercise(id = "fr-read-voyage-inoubliable-q3", kind = "choice", prompt = "Pourquoi ne voyait-on rien au début ?", options = listOf("Il y avait du brouillard", "C'était fermé", "Il pleuvait fort", "C'était la nuit"), answers = listOf("Il y avait du brouillard"), explain = "Il y avait du brouillard, donc on ne voyait rien."), Exercise(id = "fr-read-voyage-inoubliable-q4", kind = "choice", prompt = "Avec qui a-t-il dîné ?", options = listOf("Avec une famille de Cusco", "Avec la grand-mère de l'hôtel", "Seul", "Avec des amis du train"), answers = listOf("Avec une famille de Cusco"), explain = "J'ai rencontré une famille de Cusco, et ils m'ont invité à dîner."), Exercise(id = "fr-read-voyage-inoubliable-q5", kind = "written", prompt = "Que répond-il maintenant quand on lui demande une destination ?", options = listOf(), answers = listOf("perou", "perú", "le perou", "le pérou"), explain = "Je réponds le Pérou.")), skills = listOf("reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel")),
    ReadingText(id = "fr-read-chronique-pietonne", languageID = "fr", title = "Chronique : piétonnisons", level = "B2", topic = "opinion", unitID = "fr-foundations-u8", text = "Je pense qu'on devrait piétonniser le centre. D'un côté, le bruit baisserait : les habitants de la place réclament du calme depuis des années. De l'autre, la pollution baisserait, elle qui dépasse déjà les seuils légaux. C'est vrai que les commerçants craignent de perdre des clients, mais les chiffres d'autres villes disent le contraire : là où la voiture disparaît, les gens marchent plus et achètent plus. La société dont le rapport a été publié le mois dernier a calculé 15 % de ventes en plus dans les rues sans voitures. Pour tout cela, je défends la mesure : si nous avions le courage de l'essayer un an, nous ne voudrions plus revenir en arrière.", questions = listOf(Exercise(id = "fr-read-chronique-pietonne-q1", kind = "choice", prompt = "Quelle est la thèse de la chronique ?", options = listOf("Piétonniser le centre", "Élargir l'autoroute", "Interdire les vélos", "Construire un parking"), answers = listOf("Piétonniser le centre"), explain = "« Je pense qu'on devrait piétonniser le centre »."), Exercise(id = "fr-read-chronique-pietonne-q2", kind = "written", prompt = "Qu'est-ce qui dépasse les seuils légaux ?", options = listOf(), answers = listOf("la pollution"), explain = "La pollution dépasse déjà les seuils légaux."), Exercise(id = "fr-read-chronique-pietonne-q3", kind = "choice", prompt = "De quoi les commerçants ont-ils peur ?", options = listOf("De perdre des clients", "De payer plus d'impôts", "De fermer en été", "De déménager"), answers = listOf("De perdre des clients"), explain = "Ils craignent de perdre des clients."), Exercise(id = "fr-read-chronique-pietonne-q4", kind = "written", prompt = "Combien de ventes en plus dans les rues sans voitures ?", options = listOf(), answers = listOf("15%", "15 %", "quinze pour cent"), explain = "15 % de ventes en plus."), Exercise(id = "fr-read-chronique-pietonne-q5", kind = "choice", prompt = "Que propose l'auteur à la fin ?", options = listOf("L'essayer un an", "Oublier le plan", "Punir plus", "Voter encore"), answers = listOf("L'essayer un an"), explain = "« Si nous avions le courage de l'essayer un an ».")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional")),
    ReadingText(id = "fr-read-essai-ville", languageID = "fr", title = "Essai : la ville à hauteur d'homme", level = "C1", topic = "essai", unitID = "fr-foundations-u9", text = "Faut-il rendre la ville aux piétons ou aux voitures ? À mon sens, la question est mal posée : il ne s'agit pas d'exclure, mais de hiérarchiser. D'un côté, la voiture occupe un espace rare : une place de parking abrite autant de surface qu'un café. De l'autre, des millions d'habitants en dépendent, faute de transports dignes de ce nom. C'est ici que le débat mérite d'être nuancé. Réduire la place de la voiture n'est pas la supprimer ; c'est, en quelque sorte, lui rendre sa valeur. Les villes qui ont osé — Oslo, Pontevedra — constatent moins d'accidents et des commerces qui résistent. Autrement dit, maîtriser la voiture est un gain pour tous, y compris pour ceux qui conduisent. Encore faut-il investir d'abord dans les bus : sans alternative crédible, chaque contrainte devient une punition.", questions = listOf(Exercise(id = "fr-read-essai-ville-q1", kind = "choice", prompt = "Quelle est la thèse de l'essai ?", options = listOf("Hiérarchiser plutôt qu'exclure", "Interdire les voitures", "Construire plus de parkings", "Supprimer les bus"), answers = listOf("Hiérarchiser plutôt qu'exclure"), explain = "« Il ne s'agit pas d'exclure, mais de hiérarchiser »."), Exercise(id = "fr-read-essai-ville-q2", kind = "written", prompt = "Qu'abrite une place de parking, selon l'essai ?", options = listOf(), answers = listOf("autant de surface qu'un cafe", "autant de surface qu'un café", "la surface d'un café"), explain = "« Une place de parking abrite autant de surface qu'un café »."), Exercise(id = "fr-read-essai-ville-q3", kind = "choice", prompt = "Quelles villes sont citées en exemple ?", options = listOf("Oslo et Pontevedra", "Paris et Lyon", "Oslo et Paris", "Lyon et Pontevedra"), answers = listOf("Oslo et Pontevedra"), explain = "« Les villes qui ont osé — Oslo, Pontevedra »."), Exercise(id = "fr-read-essai-ville-q4", kind = "choice", prompt = "Que signifie « lui rendre sa valeur » ?", options = listOf("La voiture redevient utile en étant moins prioritaire", "La voiture disparaît", "Le prix de l'essence baisse", "La voiture reprend la ville"), answers = listOf("La voiture redevient utile en étant moins prioritaire"), explain = "Réduire sa place n'est pas la supprimer : moins partout, donc mieux utilisée."), Exercise(id = "fr-read-essai-ville-q5", kind = "written", prompt = "Quelle condition l'auteur pose-t-il à la fin ?", options = listOf(), answers = listOf("investir d'abord dans les bus", "investir dans les bus", "des transports credibles", "une alternative credible"), explain = "« Encore faut-il investir d'abord dans les bus ».")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations")),
    ReadingText(id = "fr-read-lettre-direction", languageID = "fr", title = "Lettre de la direction", level = "C1", topic = "travail", unitID = "fr-foundations-u9", text = "Chères équipes, chers collaborateurs,\n\nJe vous écris au sujet de l'organisation de la rentrée. Comme vous le savez, nos locaux du boulevard Nord seront rénovés à compter du 3 novembre. Par conséquent, les équipes du deuxième étage rejoindront le site Est, moyennant quelques aménagements que la logistique s'engage à achever avant votre arrivée. Par ailleurs, nous instaurons, à titre expérimental, deux jours de télétravail hebdomadaires ; leurs modalités vous parviendront par le portail interne. Je mesure que ces changements suscitent des questions ; aussi vous invite-je à la réunion d'information du 12 octobre, à 14 heures, salle Hemingway. En résumé : même mission, nouveaux espaces, davantage de souplesse. Je vous remercie de votre confiance et reste à votre disposition.\n\nLa direction", questions = listOf(Exercise(id = "fr-read-lettre-direction-q1", kind = "choice", prompt = "Quand les locaux du boulevard Nord seront-ils rénovés ?", options = listOf("À compter du 3 novembre", "Le 12 octobre", "Avant la rentrée", "En janvier"), answers = listOf("À compter du 3 novembre"), explain = "« Seront rénovés à compter du 3 novembre »."), Exercise(id = "fr-read-lettre-direction-q2", kind = "written", prompt = "Où iront les équipes du deuxième étage ?", options = listOf(), answers = listOf("au site est", "le site est", "site est"), explain = "« Les équipes du deuxième étage rejoindront le site Est »."), Exercise(id = "fr-read-lettre-direction-q3", kind = "choice", prompt = "Combien de jours de télétravail sont instaurés ?", options = listOf("Deux par semaine", "Trois par semaine", "Un par mois", "Aucun"), answers = listOf("Deux par semaine"), explain = "« Deux jours de télétravail hebdomadaires »."), Exercise(id = "fr-read-lettre-direction-q4", kind = "choice", prompt = "Où se tiendra la réunion d'information ?", options = listOf("Salle Hemingway", "Site Est", "Boulevard Nord", "En visioconférence"), answers = listOf("Salle Hemingway"), explain = "« Salle Hemingway » est annoncé en fin de lettre."), Exercise(id = "fr-read-lettre-direction-q5", kind = "choice", prompt = "Quel est le ton de cette lettre ?", options = listOf("Formel et rassurant", "Familier et direct", "Sec et neutre", "Désolé et défensif"), answers = listOf("Formel et rassurant"), explain = "« Chères équipes », « je reste à votre disposition », « En résumé » : registre soutenu qui rassure.")), skills = listOf("reading:detail", "reading:scan", "vocab:work", "vocab:collocations")),
    ReadingText(id = "fr-read-critique-livre", languageID = "fr", title = "Critique : un premier roman", level = "C1", topic = "littérature", unitID = "fr-foundations-u9", text = "Voilà un roman qui aurait pu sombrer dans la sentimentalité ; il s'en sort avec panache. L'auteure y suit trois générations de femmes dans une boulangerie lyonnaise : la grand-mère qui pétrit, la mère qui tient la caisse, la fille qui veut partir. À mon sens, le génie du livre tient à ses silences : rien n'est expliqué, tout est suggéré, à la manière des grandes fresques familiales. On regrettera toutefois une fin expéditive : les dernières pages résolvent en dix lignes ce que trois cents pages avaient patiemment noué. Nuance importante : ce défaut ne ruine pas l'ensemble. En résumé, un premier roman remarquable, moyennant une certaine tolérance pour les fins pressées. Il mérite sa place dans les prix littéraires de la rentrée ; je lirai le suivant, c'est dire.", questions = listOf(Exercise(id = "fr-read-critique-livre-q1", kind = "choice", prompt = "Que suit l'auteure dans ce roman ?", options = listOf("Trois générations de femmes", "Deux frères lyonnais", "Une boulangerie parisienne", "Une mère et son fils"), answers = listOf("Trois générations de femmes"), explain = "« Trois générations de femmes dans une boulangerie lyonnaise »."), Exercise(id = "fr-read-critique-livre-q2", kind = "choice", prompt = "Que signifie « il s'en sort avec panache » ?", options = listOf("Le roman évite habilement le piège", "Le roman échoue lamentablement", "L'auteure change de sujet", "Le livre est drôle"), answers = listOf("Le roman évite habilement le piège"), explain = "Il « aurait pu sombrer » mais il évite la sentimentalité avec brio."), Exercise(id = "fr-read-critique-livre-q3", kind = "written", prompt = "Que regrette la critique ?", options = listOf(), answers = listOf("une fin expeditive", "une fin expéditive", "une fin trop rapide", "les dernieres pages"), explain = "« On regrettera toutefois une fin expéditive »."), Exercise(id = "fr-read-critique-livre-q4", kind = "choice", prompt = "Quelle nuance la critique apporte-t-elle à ce défaut ?", options = listOf("Il ne ruine pas l'ensemble", "Il rend le livre inutile", "Il vient de l'éditeur", "Il prouve la mauvaise foi"), answers = listOf("Il ne ruine pas l'ensemble"), explain = "« Nuance importante : ce défaut ne ruine pas l'ensemble »."), Exercise(id = "fr-read-critique-livre-q5", kind = "choice", prompt = "Quel est le verdict global ?", options = listOf("Un premier roman remarquable", "Un livre à éviter", "Un ouvrage moyen", "Un essai passionnant"), answers = listOf("Un premier roman remarquable"), explain = "« En résumé, un premier roman remarquable ».")), skills = listOf("reading:inference", "reading:detail", "function:express-opinion", "vocab:collocations")),
    ReadingText(id = "fr-read-annonce-coloc", languageID = "fr", title = "Petite annonce : cherche colocataire", level = "A1", topic = "colocation", unitID = "fr-foundations-u10", text = "Cherche colocataire pour un grand appartement près du parc. Il y a trois chambres, une cuisine et un grand salon avec un canapé. Ma chambre est petite ; ta chambre est à côté de la salle de bains. Je m'appelle Julie, je suis étudiante et je suis très sympa. J'aime la musique et le vélo. Le loyer est de quatre cents euros. Il n'y a pas de garage, mais il y a un balcon. Tu es intéressé ? Appelle-moi le soir.", questions = listOf(Exercise(id = "fr-read-annonce-coloc-q1", kind = "choice", prompt = "Combien de chambres dans l'appartement ?", options = listOf("Trois", "Deux", "Quatre", "Une"), answers = listOf("Trois"), explain = "Il y a trois chambres."), Exercise(id = "fr-read-annonce-coloc-q2", kind = "written", prompt = "Où est la chambre du colocataire ?", options = listOf(), answers = listOf("à côté de la salle de bains", "a cote de la salle de bains"), explain = "Ta chambre est à côté de la salle de bains."), Exercise(id = "fr-read-annonce-coloc-q3", kind = "choice", prompt = "Comment est Julie ?", options = listOf("Très sympa", "Très sérieuse", "Très fatiguée", "Timide"), answers = listOf("Très sympa"), explain = "Je suis très sympa, dit Julie."), Exercise(id = "fr-read-annonce-coloc-q4", kind = "written", prompt = "Quel est le prix du loyer ?", options = listOf(), answers = listOf("quatre cents euros", "400 euros", "quatre cent euros"), explain = "Le loyer est de quatre cents euros."), Exercise(id = "fr-read-annonce-coloc-q5", kind = "choice", prompt = "Qu'est-ce qu'il n'y a pas ?", options = listOf("De garage", "De balcon", "De cuisine", "De salon"), answers = listOf("De garage"), explain = "Il n'y a pas de garage, mais il y a un balcon.")), skills = listOf("reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people")),
    ReadingText(id = "fr-read-message-groupe", languageID = "fr", title = "Messages du groupe", level = "A1", topic = "week-end", unitID = "fr-foundations-u13", text = "Léa : Salut ! Quel temps demain ?\nKarim : Il fait beau le matin, mais il pleut l'après-midi.\nLéa : Dommage ! Je fais toujours du vélo le samedi matin.\nMai : Moi, je vais à la piscine. Je nage souvent, j'adore l'eau.\nKarim : Moi, je ne lis jamais le week-end. Je joue au foot avec mon frère.\nLéa : Et le dimanche ? Vous aimez cuisiner ?\nMai : Oui ! J'aime faire des crêpes. Vous venez ?\nKarim : Super idée ! À dimanche !", questions = listOf(Exercise(id = "fr-read-message-groupe-q1", kind = "choice", prompt = "Quel temps fait-il demain après-midi ?", options = listOf("Il pleut", "Il neige", "Il fait beau", "Il fait froid"), answers = listOf("Il pleut"), explain = "Il fait beau le matin, mais il pleut l'après-midi."), Exercise(id = "fr-read-message-groupe-q2", kind = "written", prompt = "Qu'est-ce que Léa fait toujours le samedi matin ?", options = listOf(), answers = listOf("du vélo", "du velo", "elle fait toujours du vélo", "elle fait toujours du velo"), explain = "Je fais toujours du vélo le samedi matin."), Exercise(id = "fr-read-message-groupe-q3", kind = "choice", prompt = "Où va Mai ?", options = listOf("À la piscine", "Au parc", "Au marché", "À la maison"), answers = listOf("À la piscine"), explain = "Moi, je vais à la piscine, écrit Mai."), Exercise(id = "fr-read-message-groupe-q4", kind = "choice", prompt = "Qu'est-ce que Karim fait le week-end ?", options = listOf("Il joue au foot", "Il nage", "Il lit", "Il fait du vélo"), answers = listOf("Il joue au foot"), explain = "Je joue au foot avec mon frère."), Exercise(id = "fr-read-message-groupe-q5", kind = "written", prompt = "Qu'est-ce que Mai aime faire ?", options = listOf(), answers = listOf("faire des crêpes", "faire des crepes", "des crêpes", "des crepes"), explain = "J'aime faire des crêpes, écrit Mai.")), skills = listOf("reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs")),
    ReadingText(id = "it-read-gruppo-camminata", languageID = "it", title = "Il gruppo di camminata", level = "A1", topic = "salute", unitID = "it-foundations-u2", text = "Il martedì, il quartiere organizza una camminata gratis. Parte alle nove dalla piazza e arriva fino al fiume. Il gruppo è misto: ci sono studenti, famiglie e pensionati. Nessuno corre; l'idea è camminare e parlare. Alla fine, chi vuole fa colazione insieme in un bar del mercato. Giulia ci va da un mese e ha già tre amici nuovi. Dice che è il momento più tranquillo della sua settimana.", questions = listOf(Exercise(id = "it-read-gruppo-camminata-q1", kind = "choice", prompt = "Quando c'è la camminata ?", options = listOf("Il martedì", "Il lunedì", "Il sabato", "Tutti i giorni"), answers = listOf("Il martedì"), explain = "Il martedì, il quartiere organizza una camminata gratis."), Exercise(id = "it-read-gruppo-camminata-q2", kind = "written", prompt = "A che ora parte ?", options = listOf(), answers = listOf("alle nove", "le nove", "nove"), explain = "Parte alle nove dalla piazza."), Exercise(id = "it-read-gruppo-camminata-q3", kind = "choice", prompt = "Chi partecipa ?", options = listOf("Studenti, famiglie e pensionati", "Solo studenti", "Solo pensionati", "Solo famiglie"), answers = listOf("Studenti, famiglie e pensionati"), explain = "Il gruppo è misto."), Exercise(id = "it-read-gruppo-camminata-q4", kind = "choice", prompt = "Cosa fa chi vuole alla fine ?", options = listOf("Fa colazione insieme", "Corre al fiume", "Torna a casa", "Prende l'autobus"), answers = listOf("Fa colazione insieme"), explain = "Fa colazione insieme in un bar del mercato."), Exercise(id = "it-read-gruppo-camminata-q5", kind = "written", prompt = "Da quanto tempo ci va Giulia ?", options = listOf(), answers = listOf("un mese", "1 mese"), explain = "Giulia ci va da un mese.")), skills = listOf("reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine")),
    ReadingText(id = "it-read-annuncio-appartamento", languageID = "it", title = "L'annuncio dell'appartamento", level = "A2", topic = "appartamenti", unitID = "it-foundations-u4", text = "Appartamento luminoso di due camere in affitto da settembre. È al terzo piano, con ascensore, e ha un balcone che dà sul cortile, quindi è tranquillo. Il salotto è più grande della cucina, ma la cucina ha la finestra. Il quartiere ha il mercato il sabato e la fermata della metro è a cinque minuti. Non è il meno costoso della zona, ma è il migliore illuminato. Si chiede un mese di caparra e si preferisce qualcuno che lavori da casa, come gli attuali proprietari.", questions = listOf(Exercise(id = "it-read-annuncio-appartamento-q1", kind = "choice", prompt = "Quando è disponibile ?", options = listOf("Da settembre", "Da agosto", "Subito", "A gennaio"), answers = listOf("Da settembre"), explain = "In affitto da settembre."), Exercise(id = "it-read-annuncio-appartamento-q2", kind = "choice", prompt = "Perché è tranquillo ?", options = listOf("Dà sul cortile", "È al piano terra", "Non ha vicini", "È in campagna"), answers = listOf("Dà sul cortile"), explain = "Il balcone dà sul cortile, quindi è tranquillo."), Exercise(id = "it-read-annuncio-appartamento-q3", kind = "written", prompt = "A quanti minuti c'è la metro ?", options = listOf(), answers = listOf("cinque minuti", "5 minuti", "cinque"), explain = "La fermata della metro è a cinque minuti."), Exercise(id = "it-read-annuncio-appartamento-q4", kind = "choice", prompt = "Com'è rispetto alla zona ?", options = listOf("Non il meno costoso, ma il migliore illuminato", "Il meno costoso", "Il meno illuminato", "Il più piccolo"), answers = listOf("Non il meno costoso, ma il migliore illuminato"), explain = "Non è il meno costoso, ma è il migliore illuminato."), Exercise(id = "it-read-annuncio-appartamento-q5", kind = "choice", prompt = "Chi preferiscono i proprietari ?", options = listOf("Qualcuno che lavori da casa", "Studenti", "Famiglie con bambini", "Pensionati"), answers = listOf("Qualcuno che lavori da casa"), explain = "Si preferisce qualcuno che lavori da casa.")), skills = listOf("reading:detail", "reading:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ReadingText(id = "it-read-viaggio-indimenticabile", languageID = "it", title = "Il viaggio indimenticabile", level = "B1", topic = "viaggi", unitID = "it-foundations-u6", text = "L'estate scorsa ho fatto il viaggio dei miei sogni: quindici giorni in Perù. Avevo già visitato il Messico e l'Argentina, ma il Sud America mi ha ancora sorpreso. Il terzo giorno sono salito al Machu Picchu. C'era nebbia, così all'inizio non si vedeva niente. Poi, poco a poco, è uscito il sole ed è apparsa la città intera. Non ho detto niente; sono rimasto a guardare. Sul treno del ritorno ho conosciuto una famiglia di Cusco, e mi hanno invitato a cena. « I viaggiatori dicono sempre la stessa cosa », ha riso la nonna, « ma questa zuppa è vera ». Aveva ragione: è stata la migliore cena del viaggio. Da allora, ogni volta che qualcuno chiede una destinazione, io rispondo il Perù.", questions = listOf(Exercise(id = "it-read-viaggio-indimenticabile-q1", kind = "choice", prompt = "Quanto è durato il viaggio ?", options = listOf("Quindici giorni", "Dieci giorni", "Un mese", "Tre giorni"), answers = listOf("Quindici giorni"), explain = "Quindici giorni in Perù."), Exercise(id = "it-read-viaggio-indimenticabile-q2", kind = "written", prompt = "Quali paesi aveva già visitato ?", options = listOf(), answers = listOf("messico e argentina", "il messico e l'argentina"), explain = "Avevo già visitato il Messico e l'Argentina."), Exercise(id = "it-read-viaggio-indimenticabile-q3", kind = "choice", prompt = "Perché non si vedeva niente all'inizio ?", options = listOf("C'era nebbia", "Era chiuso", "Pioveva forte", "Era di notte"), answers = listOf("C'era nebbia"), explain = "C'era nebbia, così non si vedeva niente."), Exercise(id = "it-read-viaggio-indimenticabile-q4", kind = "choice", prompt = "Con chi ha cenato il narratore ?", options = listOf("Con una famiglia di Cusco", "Con la nonna dell'albergo", "Da solo", "Con amici del treno"), answers = listOf("Con una famiglia di Cusco"), explain = "Ho conosciuto una famiglia di Cusco e mi hanno invitato a cena."), Exercise(id = "it-read-viaggio-indimenticabile-q5", kind = "written", prompt = "Cosa risponde ora quando gli chiedono una destinazione ?", options = listOf(), answers = listOf("peru", "perù", "il peru", "il perù"), explain = "Io rispondo il Perù.")), skills = listOf("reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel")),
    ReadingText(id = "it-read-colonna-pedonale", languageID = "it", title = "Colonna: pedonalizziamo", level = "B2", topic = "opinione", unitID = "it-foundations-u8", text = "Penso che dovremmo pedonalizzare il centro. Da un lato, calerebbe il rumore: i residenti della piazza chiedono silenzio da anni. Dall'altro, calerebbe l'inquinamento, che supera già i limiti legali. È vero che i negozianti temono di perdere clienti, ma i numeri di altre città dicono il contrario: dove sparisce l'auto, la gente cammina di più e compra di più. La società il cui rapporto è stato pubblicato il mese scorso ha calcolato un 15 % di vendite in più nelle strade senza traffico. Per tutto questo, difendo la misura: se avessimo il coraggio di provarla un anno, non vorremmo più tornare indietro.", questions = listOf(Exercise(id = "it-read-colonna-pedonale-q1", kind = "choice", prompt = "Qual è la tesi della colonna ?", options = listOf("Pedonalizzare il centro", "Allargare l'autostrada", "Vietare le bici", "Costruire un parcheggio"), answers = listOf("Pedonalizzare il centro"), explain = "« Penso che dovremmo pedonalizzare il centro »."), Exercise(id = "it-read-colonna-pedonale-q2", kind = "written", prompt = "Cosa supera già i limiti legali ?", options = listOf(), answers = listOf("l'inquinamento", "inquinamento"), explain = "L'inquinamento supera i limiti legali."), Exercise(id = "it-read-colonna-pedonale-q3", kind = "choice", prompt = "Di cosa hanno paura i negozianti ?", options = listOf("Di perdere clienti", "Di pagare più tasse", "Di chiudere d'estate", "Di traslocare"), answers = listOf("Di perdere clienti"), explain = "Temono di perdere clienti."), Exercise(id = "it-read-colonna-pedonale-q4", kind = "written", prompt = "Quanto in più venderebbero le strade senza traffico ?", options = listOf(), answers = listOf("15%", "un 15%", "quindici per cento", "15 per cento"), explain = "Un 15 % di vendite in più."), Exercise(id = "it-read-colonna-pedonale-q5", kind = "choice", prompt = "Cosa propone l'autore alla fine ?", options = listOf("Provarla un anno", "Dimenticare il piano", "Multare di più", "Votare ancora"), answers = listOf("Provarla un anno"), explain = "« Se avessimo il coraggio di provarla un anno ».")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional")),
    ReadingText(id = "it-read-saggio-citta", languageID = "it", title = "Saggio: la città che cammina", level = "C1", topic = "città", unitID = "it-foundations-u9", text = "La città che cammina è, per così dire, una città che pensa. Negli ultimi decenni abbiamo sacrificato lo spazio pubblico alla velocità: parcheggi dove potevano crescere alberi, corsie dove potevano stare i bambini. Non si tratta di nostalgia, bensì di equilibrio. Le città che hanno ridotto il traffico nel centro storico — Oslo, Pontevedra — non hanno registrato il collasso commerciale temuto; hanno anzi visto crescere i piccoli commerci, che vivono di passanti lenti. A mio avviso, il vero ostacolo non è economico ma culturale: confondiamo la libertà di muoversi in auto con la libertà di abitare la città. In sintesi, ridisegnare le strade significa decidere chi le strade devono servire: se la risposta sono le persone, il resto è tecnica.", questions = listOf(Exercise(id = "it-read-saggio-citta-q1", kind = "choice", prompt = "Qual è la tesi centrale del saggio?", options = listOf("Ridisegnare le strade per le persone", "Difendere la velocità in auto", "Tornare al passato per nostalgia", "Spostare i negozi fuori città"), answers = listOf("Ridisegnare le strade per le persone"), explain = "« Ridisegnare le strade significa decidere chi devono servire »."), Exercise(id = "it-read-saggio-citta-q2", kind = "choice", prompt = "Come definisce l'autore il vero ostacolo?", options = listOf("Culturale, non economico", "Economico, non culturale", "Tecnico e inevitabile", "Politico e temporaneo"), answers = listOf("Culturale, non economico"), explain = "« Il vero ostacolo non è economico ma culturale »."), Exercise(id = "it-read-saggio-citta-q3", kind = "written", prompt = "Cosa hanno visto crescere le città che hanno ridotto il traffico?", options = listOf(), answers = listOf("i piccoli commerci", "piccoli commerci", "i piccoli esercizi commerciali"), explain = "Hanno visto crescere i piccoli commerci."), Exercise(id = "it-read-saggio-citta-q4", kind = "choice", prompt = "Quali città vengono citate come esempio?", options = listOf("Oslo e Pontevedra", "Roma e Milano", "Parigi e Berlino", "Osaka e Kyoto"), answers = listOf("Oslo e Pontevedra"), explain = "Citati Oslo e Pontevedra."), Exercise(id = "it-read-saggio-citta-q5", kind = "written", prompt = "Con cosa confondiamo, secondo l'autore, la libertà di abitare la città?", options = listOf(), answers = listOf("con la liberta di muoversi in auto", "con la libertà di muoversi in auto", "muoversi in auto"), explain = "Con la libertà di muoversi in auto."), Exercise(id = "it-read-saggio-citta-q6", kind = "choice", prompt = "Che funzione ha « bensì » nel testo?", options = listOf("Contrastare dopo una negazione", "Aggiungere un esempio", "Introdurre una causa", "Chiudere il ragionamento"), answers = listOf("Contrastare dopo una negazione"), explain = "« Non… bensì »: correzione dopo la negazione.")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations")),
    ReadingText(id = "it-read-lettera-dirigenza", languageID = "it", title = "Lettera alla dirigenza", level = "C1", topic = "lavoro", unitID = "it-foundations-u9", text = "Gentile Direzione, Le scrivo per conto del gruppo operativo per sottoporreLe una proposta sul lavoro ibrido. Nei sei mesi di sperimentazione, i rilasci sono stati puntuali e i tempi di risposta sono rimasti stabili; peraltro, il sondaggio interno mostra un netto miglioramento del benessere dichiarato. È vero che alcuni processi, per così dire faccia a faccia, richiedono presenza: pertanto proponiamo tre giorni in sede per i team di produzione e due per gli altri reparti. In sintesi, chiediamo di rendere strutturale quanto finora sperimentato, con una revisione semestrale. Restiamo a Sua completa disposizione per presentare i dati in riunione e La ringraziamo sin d'ora per l'attenzione. Distinti saluti, Il gruppo operativo.", questions = listOf(Exercise(id = "it-read-lettera-dirigenza-q1", kind = "choice", prompt = "Cosa chiede il gruppo operativo?", options = listOf("Rendere strutturale il lavoro ibrido", "Tornare tutti in ufficio cinque giorni", "Assumere nuovo personale", "Posticipare la sperimentazione"), answers = listOf("Rendere strutturale il lavoro ibrido"), explain = "« Chiediamo di rendere strutturale quanto finora sperimentato »."), Exercise(id = "it-read-lettera-dirigenza-q2", kind = "written", prompt = "Quanti giorni in sede propongono per i team di produzione?", options = listOf(), answers = listOf("tre", "3", "tre giorni"), explain = "Tre giorni in sede."), Exercise(id = "it-read-lettera-dirigenza-q3", kind = "choice", prompt = "Quali dati portano a favore?", options = listOf("Rilasci puntuali e tempi di risposta stabili", "Vendite raddoppiate", "Meno ferie richieste", "Più clienti acquisiti"), answers = listOf("Rilasci puntuali e tempi di risposta stabili"), explain = "Rilasci puntuali, tempi stabili, benessere in crescita."), Exercise(id = "it-read-lettera-dirigenza-q4", kind = "choice", prompt = "Quale concessione fa la lettera?", options = listOf("Alcuni processi richiedono la presenza", "Il sondaggio è inaffidabile", "I tempi sono peggiorati", "La proposta è solo teorica"), answers = listOf("Alcuni processi richiedono la presenza"), explain = "« È vero che alcuni processi richiedono presenza »."), Exercise(id = "it-read-lettera-dirigenza-q5", kind = "written", prompt = "Con quale frequenza chiedono la revisione?", options = listOf(), answers = listOf("semestrale", "ogni sei mesi", "una revisione semestrale"), explain = "Revisione semestrale."), Exercise(id = "it-read-lettera-dirigenza-q6", kind = "choice", prompt = "Che funzione ha « peraltro »?", options = listOf("Aggiungere un argomento a favore", "Contrastare quanto detto", "Annunciare la conclusione", "Esprimere un dubbio"), answers = listOf("Aggiungere un argomento a favore"), explain = "Peraltro: argomento aggiuntivo.")), skills = listOf("reading:detail", "reading:scan", "vocab:work", "grammar:connectors")),
    ReadingText(id = "it-read-recensione-critica", languageID = "it", title = "Recensione critica", level = "C1", topic = "cultura", unitID = "it-foundations-u9", text = "Al debutto, il romanzo di Vera Antonelli affascina: una voce netta, un quartiere di periferia ricostruito con precisione chirurgica. A metà libro, però, la trama incrina: la protagonista, che aveva deciso da sola, improvvisamente si affida al caso, e il lettore perde il gusto di accompagnarla. Non è un difetto minore, perché la forza del romanzo stava proprio in quella volontà. In un certo senso, l'autrice ha scelto la strada più comoda proprio quando il lettore le aveva concesso la più difficile. Eppure il finale riesce: le ultime trenta pagine, quasi senza dialoghi, tengono insieme ciò che il centro aveva disfatto. A mio avviso, Antonelli è una scrittrice da seguire: questo romanzo è una promessa più che un risultato, ma di promesse così se ne vedono poche.", questions = listOf(Exercise(id = "it-read-recensione-critica-q1", kind = "choice", prompt = "Che difetto segnala la recensora a metà libro?", options = listOf("La protagonista si affida al caso", "Troppi dialoghi", "Un finale frettoloso", "Un'ambientazione confusa"), answers = listOf("La protagonista si affida al caso"), explain = "La protagonista improvvisamente si affida al caso."), Exercise(id = "it-read-recensione-critica-q2", kind = "choice", prompt = "Come giudica il finale?", options = listOf("Riesce a tenere insieme il romanzo", "Rovina tutto", "È troppo lungo", "Manca del tutto"), answers = listOf("Riesce a tenere insieme il romanzo"), explain = "« Il finale riesce » e tiene insieme il romanzo."), Exercise(id = "it-read-recensione-critica-q3", kind = "written", prompt = "Quante pagine finali tengono insieme il romanzo?", options = listOf(), answers = listOf("trenta", "30", "le ultime trenta pagine"), explain = "Le ultime trenta pagine."), Exercise(id = "it-read-recensione-critica-q4", kind = "choice", prompt = "Che senso ha « una promessa più che un risultato »?", options = listOf("Il talento c'è, ma il libro non lo esaurisce", "Il libro è un fallimento", "È un libro per giovani lettori", "È una biografia"), answers = listOf("Il talento c'è, ma il libro non lo esaurisce"), explain = "Talento reale, risultato non ancora pieno."), Exercise(id = "it-read-recensione-critica-q5", kind = "written", prompt = "Dove stava la forza del romanzo secondo la recensora?", options = listOf(), answers = listOf("nella volonta della protagonista", "nella volontà della protagonista", "nella determinazione della protagonista"), explain = "Nella volontà della protagonista."), Exercise(id = "it-read-recensione-critica-q6", kind = "choice", prompt = "Che tono ha la recensione?", options = listOf("Critico ma benevolo", "Ostile", "Entusiasta senza riserve", "Indifferente"), answers = listOf("Critico ma benevolo"), explain = "Rilievi severi, chiusura incoraggiante.")), skills = listOf("reading:inference", "reading:detail", "function:express-opinion", "vocab:collocations")),
    ReadingText(id = "it-read-annuncio-coinquilino", languageID = "it", title = "Cerco un coinquilino", level = "A1", topic = "casa", unitID = "it-foundations-u10", text = "CERCO COINQUILINO — L'appartamento è in via Verdi 10, vicino al parco. Ci sono due camere, una cucina e un bagno. La mia camera è piccola; la tua camera è grande e luminosa. C'è un divano nel soggiorno e ci sono due bici nel balcone. Il mio gatto si chiama Micio. Io lavoro in una libreria e sono tranquillo. Il tuo affitto è di 300 euro. Scrivimi a micio@posta.it !", questions = listOf(Exercise(id = "it-read-annuncio-coinquilino-q1", kind = "choice", prompt = "Quante camere ci sono nell'appartamento ?", options = listOf("Due", "Una", "Tre", "Quattro"), answers = listOf("Due"), explain = "« Ci sono due camere, una cucina e un bagno »."), Exercise(id = "it-read-annuncio-coinquilino-q2", kind = "choice", prompt = "Com'è la camera del nuovo coinquilino ?", options = listOf("Grande e luminosa", "Piccola e scura", "Piccola e luminosa", "Senza finestre"), answers = listOf("Grande e luminosa"), explain = "« La tua camera è grande e luminosa »."), Exercise(id = "it-read-annuncio-coinquilino-q3", kind = "written", prompt = "Com'è la camera di chi scrive ?", options = listOf(), answers = listOf("piccola", "e piccola", "la camera e piccola"), explain = "« La mia camera è piccola »."), Exercise(id = "it-read-annuncio-coinquilino-q4", kind = "written", prompt = "Dov'è l'appartamento ?", options = listOf(), answers = listOf("in via Verdi 10", "via Verdi 10", "in via Verdi dieci"), explain = "« L'appartamento è in via Verdi 10 »."), Exercise(id = "it-read-annuncio-coinquilino-q5", kind = "choice", prompt = "Quanto costa l'affitto ?", options = listOf("300 euro", "30 euro", "350 euro", "Non è scritto"), answers = listOf("300 euro"), explain = "« Il tuo affitto è di 300 euro ».")), skills = listOf("reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people")),
    ReadingText(id = "it-read-messaggio-gruppo", languageID = "it", title = "Il gruppo del weekend", level = "A1", topic = "weekend", unitID = "it-foundations-u13", text = "GRUPPO « WEEKEND » — Giulia: Ragazzi, sabato c'è il sole ! Che facciamo ? Marco: Io di solito nuoto la mattina, ma questo sabato sono libero dopo le quattro. Giulia: Allora bicicletta al parco alle cinque ? Anna: Mi piace ! Io corro spesso al parco, ma in bici non vado mai. Marco: Perfetto. Dopo, pizza da Franco ? Anna: Sì ! Il sabato mangio sempre la pizza. Giulia: D'accordo: bici alle cinque e pizza alle otto !", questions = listOf(Exercise(id = "it-read-messaggio-gruppo-q1", kind = "choice", prompt = "Che tempo fa sabato ?", options = listOf("C'è il sole", "Piove", "Nevica", "Fa freddo"), answers = listOf("C'è il sole"), explain = "« Sabato c'è il sole »."), Exercise(id = "it-read-messaggio-gruppo-q2", kind = "written", prompt = "Cosa fa di solito Marco la mattina ?", options = listOf(), answers = listOf("nuota", "nuoto", "nuotare"), explain = "« Io di solito nuoto la mattina »."), Exercise(id = "it-read-messaggio-gruppo-q3", kind = "choice", prompt = "Che cosa fa spesso Anna al parco ?", options = listOf("Corre", "Va in bici", "Legge", "Nuota"), answers = listOf("Corre"), explain = "« Io corro spesso al parco »."), Exercise(id = "it-read-messaggio-gruppo-q4", kind = "written", prompt = "Cosa non fa mai Anna ?", options = listOf(), answers = listOf("va in bici", "andare in bici", "vado in bici"), explain = "« Ma in bici non vado mai »."), Exercise(id = "it-read-messaggio-gruppo-q5", kind = "choice", prompt = "A che ora è la pizza ?", options = listOf("Alle otto", "Alle cinque", "Alle quattro", "Alle nove"), answers = listOf("Alle otto"), explain = "« Bici alle cinque e pizza alle otto ».")), skills = listOf("reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs")),
    ReadingText(id = "pt-read-grupo-caminhada", languageID = "pt", title = "O grupo de caminhada", level = "A1", topic = "saúde", unitID = "pt-foundations-u2", text = "Às terças, o bairro organiza uma caminhada grátis. Começa às nove na praça e termina no rio. O grupo é misto: tem estudantes, famílias e aposentados. Ninguém corre; a ideia é caminhar e conversar. No fim, quem quiser toma café da manhã junto num bar da feira. Bia participa faz um mês e já tem três amigos novos. Ela diz que é a hora mais tranquila da semana dela.", questions = listOf(Exercise(id = "pt-read-grupo-caminhada-q1", kind = "choice", prompt = "Quando é a caminhada ?", options = listOf("Às terças", "Às segundas", "Aos sábados", "Todos os dias"), answers = listOf("Às terças"), explain = "Às terças, o bairro organiza uma caminhada grátis."), Exercise(id = "pt-read-grupo-caminhada-q2", kind = "written", prompt = "A que horas começa ?", options = listOf(), answers = listOf("as nove", "às nove", "nove horas"), explain = "Começa às nove na praça."), Exercise(id = "pt-read-grupo-caminhada-q3", kind = "choice", prompt = "Quem participa ?", options = listOf("Estudantes, famílias e aposentados", "Só estudantes", "Só aposentados", "Só famílias"), answers = listOf("Estudantes, famílias e aposentados"), explain = "O grupo é misto."), Exercise(id = "pt-read-grupo-caminhada-q4", kind = "choice", prompt = "O que faz quem quiser no fim ?", options = listOf("Toma café da manhã junto", "Corre até o rio", "Volta para casa", "Pega o ônibus"), answers = listOf("Toma café da manhã junto"), explain = "Toma café da manhã junto num bar da feira."), Exercise(id = "pt-read-grupo-caminhada-q5", kind = "written", prompt = "Há quanto tempo a Bia participa ?", options = listOf(), answers = listOf("um mes", "um mês", "1 mês", "1 mes"), explain = "A Bia participa faz um mês.")), skills = listOf("reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine")),
    ReadingText(id = "pt-read-anuncio-apartamento", languageID = "pt", title = "O anúncio do apartamento", level = "A2", topic = "apartamentos", unitID = "pt-foundations-u4", text = "Apartamento claro de dois quartos para alugar a partir de setembro. Fica no terceiro andar, com elevador, e tem uma varanda para o pátio, então é tranquilo. A sala é maior que a cozinha, mas a cozinha tem janela. O bairro tem feira aos sábados e a estação de metrô fica a cinco minutos. Não é o mais barato da região, mas é o melhor iluminado. Pedem um mês de caução e preferem alguém que trabalhe de casa, como os atuais donos.", questions = listOf(Exercise(id = "pt-read-anuncio-apartamento-q1", kind = "choice", prompt = "Quando está disponível ?", options = listOf("A partir de setembro", "A partir de agosto", "Agora", "Em janeiro"), answers = listOf("A partir de setembro"), explain = "Para alugar a partir de setembro."), Exercise(id = "pt-read-anuncio-apartamento-q2", kind = "choice", prompt = "Por que é tranquilo ?", options = listOf("Varanda para o pátio", "Fica no térreo", "Não tem vizinhos", "Fica no campo"), answers = listOf("Varanda para o pátio"), explain = "A varanda dá para o pátio, então é tranquilo."), Exercise(id = "pt-read-anuncio-apartamento-q3", kind = "written", prompt = "A quantos minutos fica o metrô ?", options = listOf(), answers = listOf("cinco minutos", "5 minutos", "cinco"), explain = "A estação de metrô fica a cinco minutos."), Exercise(id = "pt-read-anuncio-apartamento-q4", kind = "choice", prompt = "Como é comparado com a região ?", options = listOf("Não é o mais barato, mas é o melhor iluminado", "É o mais barato", "É o pior iluminado", "É o menor"), answers = listOf("Não é o mais barato, mas é o melhor iluminado"), explain = "Não é o mais barato, mas é o melhor iluminado."), Exercise(id = "pt-read-anuncio-apartamento-q5", kind = "choice", prompt = "Quem os donos preferem ?", options = listOf("Alguém que trabalhe de casa", "Estudantes", "Famílias com crianças", "Aposentados"), answers = listOf("Alguém que trabalhe de casa"), explain = "Preferem alguém que trabalhe de casa.")), skills = listOf("reading:detail", "reading:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")),
    ReadingText(id = "pt-read-viagem-inesquecivel", languageID = "pt", title = "A viagem inesquecível", level = "B1", topic = "viagens", unitID = "pt-foundations-u6", text = "No ano passado fiz a viagem dos meus sonhos: quinze dias no Peru. Já tinha conhecido o México e a Argentina, mas a América do Sul ainda me surpreendeu. No terceiro dia subi ao Machu Picchu. Estava com neblina, então no começo não dava para ver nada. Depois, aos poucos, o sol apareceu e a cidade inteira surgiu. Não disse nada; fiquei olhando. No trem de volta conheci uma família de Cusco, e me chamaram para jantar. « Os viajantes sempre dizem a mesma coisa », riu a avó, « mas essa sopa é de verdade ». Ela tinha razão: foi o melhor jantar da viagem. Desde então, quando alguém pergunta por um destino, eu digo Peru.", questions = listOf(Exercise(id = "pt-read-viagem-inesquecivel-q1", kind = "choice", prompt = "Quanto durou a viagem ?", options = listOf("Quinze dias", "Dez dias", "Um mês", "Três dias"), answers = listOf("Quinze dias"), explain = "Quinze dias no Peru."), Exercise(id = "pt-read-viagem-inesquecivel-q2", kind = "written", prompt = "Que países ele já tinha conhecido ?", options = listOf(), answers = listOf("mexico e argentina", "méxico e argentina"), explain = "Já tinha conhecido o México e a Argentina."), Exercise(id = "pt-read-viagem-inesquecivel-q3", kind = "choice", prompt = "Por que não dava para ver nada no começo ?", options = listOf("Estava com neblina", "Estava fechado", "Chovia forte", "Era de noite"), answers = listOf("Estava com neblina"), explain = "Estava com neblina, então não se via nada."), Exercise(id = "pt-read-viagem-inesquecivel-q4", kind = "choice", prompt = "Com quem jantou o narrador ?", options = listOf("Com uma família de Cusco", "Com a avó do hotel", "Sozinho", "Com amigos do trem"), answers = listOf("Com uma família de Cusco"), explain = "Conheci uma família de Cusco e me chamaram para jantar."), Exercise(id = "pt-read-viagem-inesquecivel-q5", kind = "written", prompt = "O que ele diz agora quando perguntam por um destino ?", options = listOf(), answers = listOf("peru", "eu digo peru", "digo peru"), explain = "Eu digo Peru.")), skills = listOf("reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel")),
    ReadingText(id = "pt-read-coluna-peatonal", languageID = "pt", title = "Coluna: peatonalizemos", level = "B2", topic = "opinião", unitID = "pt-foundations-u8", text = "Acho que deveríamos peatonalizar o centro. Por um lado, o barulho cairia: os moradores da praça pedem silêncio há anos. Por outro, a poluição cairia — ela já passa dos limites legais. É verdade que o comércio teme perder clientes, mas os números de outras cidades dizem o contrário: onde o carro desaparece, a gente caminha mais e compra mais. A empresa cujo relatório foi publicado no mês passado calculou 15 % mais vendas nas ruas sem carros. Por tudo isso, defendo a medida: se tivéssemos coragem de testá-la por um ano, não ia querer voltar atrás.", questions = listOf(Exercise(id = "pt-read-coluna-peatonal-q1", kind = "choice", prompt = "Qual é a tese da coluna ?", options = listOf("Peatonalizar o centro", "Alargar a rodovia", "Proibir bicicletas", "Construir um estacionamento"), answers = listOf("Peatonalizar o centro"), explain = "« Deveríamos peatonalizar o centro »."), Exercise(id = "pt-read-coluna-peatonal-q2", kind = "written", prompt = "O que já passa dos limites legais ?", options = listOf(), answers = listOf("a poluicao", "a poluição"), explain = "A poluição já passa dos limites legais."), Exercise(id = "pt-read-coluna-peatonal-q3", kind = "choice", prompt = "De que o comércio teme ?", options = listOf("Perder clientes", "Pagar mais impostos", "Fechar no verão", "Mudar de cidade"), answers = listOf("Perder clientes"), explain = "O comércio teme perder clientes."), Exercise(id = "pt-read-coluna-peatonal-q4", kind = "written", prompt = "Quanto mais vendas nas ruas sem carros ?", options = listOf(), answers = listOf("15%", "15 %", "quinze por cento"), explain = "15 % mais vendas."), Exercise(id = "pt-read-coluna-peatonal-q5", kind = "choice", prompt = "O que o autor propõe no fim ?", options = listOf("Testar por um ano", "Esquecer o plano", "Multar mais", "Votar de novo"), answers = listOf("Testar por um ano"), explain = "« Testá-la por um ano ».")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional")),
    ReadingText(id = "pt-read-ensaio-cidade", languageID = "pt", title = "Ensaio: a língua na praça", level = "C1", topic = "opinião", unitID = "pt-foundations-u9", text = "Costuma-se dizer que a internet empobrece a língua. Na minha visão, o diagnóstico é apressado. É verdade que o teclado abrevia — « vc », « pq », « hj » —, mas abreviar não é destruir; por assim dizer, a escrita digital criou um registro novo, oral na sintaxe e escrito na forma. De certa forma, o português sempre fez isso: o que se falava na praça há um século entrou nos romances de hoje. Além disso, nunca se escreveu tanto quanto agora — mensagens, comentários, resenhas. O problema não é a variedade; é a distância entre quem domina os registros e quem fica preso em um só. Por isso, em vez de condenar o « pq », ensinemos quando ele cabe — e quando, no e-mail para a diretoria, precisa virar fórmula formal: visto que o registro é, antes de tudo, uma escolha.", questions = listOf(Exercise(id = "pt-read-ensaio-cidade-q1", kind = "choice", prompt = "Qual é a tese do ensaio ?", options = listOf("A internet não empobrece a língua", "A internet destrói a escrita", "É preciso proibir abreviações", "Ninguém escreve mais"), answers = listOf("A internet não empobrece a língua"), explain = "O autor considera apressado dizer que a internet empobrece a língua."), Exercise(id = "pt-read-ensaio-cidade-q2", kind = "written", prompt = "Que abreviações o texto cita ?", options = listOf(), answers = listOf("vc pq hj", "vc, pq e hj"), explain = "« vc », « pq », « hj »."), Exercise(id = "pt-read-ensaio-cidade-q3", kind = "choice", prompt = "O que, segundo o autor, já acontecia há um século ?", options = listOf("A fala da praça entrava nos livros", "Ninguém sabia escrever", "Os romances eram orais", "A escola proibia gírias"), answers = listOf("A fala da praça entrava nos livros"), explain = "« O que se falava na praça há um século entrou nos romances de hoje »."), Exercise(id = "pt-read-ensaio-cidade-q4", kind = "written", prompt = "Qual é, para o autor, o verdadeiro problema ?", options = listOf(), answers = listOf("a distancia entre quem domina os registros e quem fica preso em um so", "a distância entre quem domina os registros", "ficar preso em um só registro"), explain = "« A distância entre quem domina os registros e quem fica preso em um só »."), Exercise(id = "pt-read-ensaio-cidade-q5", kind = "choice", prompt = "O que o autor propõe no final ?", options = listOf("Ensinar quando cada registro cabe", "Banir o « pq » da escola", "Escrever só e-mails formais", "Parar de usar a internet"), answers = listOf("Ensinar quando cada registro cabe"), explain = "Em vez de condenar, ensinar quando o registro cabe.")), skills = listOf("reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations")),
    ReadingText(id = "pt-read-carta-diretoria", languageID = "pt", title = "Carta da diretoria", level = "C1", topic = "trabalho", unitID = "pt-foundations-u9", text = "Prezadas equipes, confirmamos com esta carta o regime híbrido vigente a partir de 3 de março: três dias presenciais, reservados à colaboração e às reuniões de time. Solicitamos que as áreas publiquem seus calendários até 20 de fevereiro, visto que as salas serão alocadas por ordem de registro. Segue em anexo o guia de boas práticas; dele constam as exceções — licenças, saúde e prazos críticos. Registramos, no entanto, que nenhuma decisão do programa reduzirá o trabalho remoto já contratado. Agradecemos desde já o empenho de todos na transição e permanecemos à disposição para esclarecimentos pelos canais habituais. Atenciosamente, Diretoria de Pessoas.", questions = listOf(Exercise(id = "pt-read-carta-diretoria-q1", kind = "choice", prompt = "Quando começa o regime híbrido ?", options = listOf("3 de março", "20 de fevereiro", "3 de fevereiro", "Em anexo"), answers = listOf("3 de março"), explain = "« Vigente a partir de 3 de março »."), Exercise(id = "pt-read-carta-diretoria-q2", kind = "written", prompt = "Até quando as áreas devem publicar os calendários ?", options = listOf(), answers = listOf("20 de fevereiro", "ate 20 de fevereiro"), explain = "« Até 20 de fevereiro »."), Exercise(id = "pt-read-carta-diretoria-q3", kind = "choice", prompt = "Como as salas serão alocadas ?", options = listOf("Por ordem de registro", "Por sorteio", "Por antiguidade", "Por indicação"), answers = listOf("Por ordem de registro"), explain = "« As salas serão alocadas por ordem de registro »."), Exercise(id = "pt-read-carta-diretoria-q4", kind = "written", prompt = "O que segue em anexo na carta ?", options = listOf(), answers = listOf("o guia de boas praticas", "guia de boas práticas", "o guia"), explain = "Segue em anexo o guia de boas práticas."), Exercise(id = "pt-read-carta-diretoria-q5", kind = "choice", prompt = "O que a carta garante sobre o trabalho remoto ?", options = listOf("Nada do programa o reduz", "Ele acaba em março", "Só diretores o mantêm", "Depende do cliente"), answers = listOf("Nada do programa o reduz"), explain = "« Nenhuma decisão do programa reduzirá o trabalho remoto já contratado ».")), skills = listOf("reading:scan", "reading:detail", "vocab:work", "grammar:connectors")),
    ReadingText(id = "pt-read-resenha-critica", languageID = "pt", title = "Resenha: Vozes do prédio", level = "C1", topic = "cultura", unitID = "pt-foundations-u9", text = "Diria que « Vozes do prédio » não é um romance fácil — e é justamente aí que mora o seu valor. A trama é mínima: uma síndica, três inquilinos e uma carta que ninguém quer ter escrito. De certa forma, nada acontece; por assim dizer, o livro inteiro é uma conversa à porta do elevador. E, no entanto, cada capítulo afia um registro: o formal da síndica, o coloquial do porteiro, o burocrático das circulares. Na minha visão, o segundo ato vacila — a autora explica o que o leitor já havia inferido. Não deixa de ser leitura imprescindível: raramente a prosa brasileira escutou tão bem quem fala como pode. Resumindo: um romance sobre registros que é, ele próprio, uma aula de registros.", questions = listOf(Exercise(id = "pt-read-resenha-critica-q1", kind = "choice", prompt = "Onde mora o valor do romance, segundo a resenha ?", options = listOf("Na sua dificuldade", "No seu final feliz", "No seu tamanho", "No seu preço"), answers = listOf("Na sua dificuldade"), explain = "« Não é um romance fácil — e é justamente aí que mora o seu valor »."), Exercise(id = "pt-read-resenha-critica-q2", kind = "written", prompt = "Quantos personagens centrais a trama tem ?", options = listOf(), answers = listOf("tres", "três", "quatro com a carta"), explain = "Uma síndica e três inquilinos: três personagens."), Exercise(id = "pt-read-resenha-critica-q3", kind = "choice", prompt = "O que a resenha critica no segundo ato ?", options = listOf("A autora explica o inferido", "Faltam capítulos", "O porteiro desaparece", "A carta é falsa"), answers = listOf("A autora explica o inferido"), explain = "« A autora explica o que o leitor já havia inferido »."), Exercise(id = "pt-read-resenha-critica-q4", kind = "choice", prompt = "O veredito final da resenhista é que a leitura é:", options = listOf("Imprescindível", "Descartável", "Confusa", "Inacabada"), answers = listOf("Imprescindível"), explain = "« Não deixa de ser leitura imprescindível »."), Exercise(id = "pt-read-resenha-critica-q5", kind = "written", prompt = "Como a resenhista resume o livro ?", options = listOf(), answers = listOf("um romance sobre registros que e uma aula de registros", "um romance sobre registros", "uma aula de registros"), explain = "« Um romance sobre registros que é, ele próprio, uma aula de registros ».")), skills = listOf("reading:inference", "function:express-opinion", "writing:argument")),
    ReadingText(id = "pt-read-anuncio-colega", languageID = "pt", title = "Anúncio: procuro colega de casa", level = "A1", topic = "casa", unitID = "pt-foundations-u10", text = "Procuro uma colega de casa para o meu apartamento na Vila Madalena. O apartamento tem dois quartos: o meu é pequeno e o seu é grande, com uma janela para a rua. A sala é clara e tem um sofá confortável. Eu sou o Pedro, tenho vinte e seis anos, sou professor e cozinho nos fins de semana. Minha rotina é tranquila: trabalho de manhã e leio à noite. Você é organizada e não fuma ? Manda uma mensagem para mim!", questions = listOf(Exercise(id = "pt-read-anuncio-colega-q1", kind = "choice", prompt = "Quantos quartos tem o apartamento?", options = listOf("Dois", "Um", "Três", "Quatro"), answers = listOf("Dois"), explain = "O apartamento tem dois quartos."), Exercise(id = "pt-read-anuncio-colega-q2", kind = "choice", prompt = "Como é o quarto do Pedro?", options = listOf("É pequeno", "É grande", "Não tem janela", "É escuro"), answers = listOf("É pequeno"), explain = "O meu é pequeno e o seu é grande, com uma janela para a rua."), Exercise(id = "pt-read-anuncio-colega-q3", kind = "choice", prompt = "Qual é o trabalho do Pedro?", options = listOf("Professor", "Médico", "Estudante", "Garçom"), answers = listOf("Professor"), explain = "Eu sou o Pedro, tenho vinte e seis anos, sou professor."), Exercise(id = "pt-read-anuncio-colega-q4", kind = "written", prompt = "O que o Pedro faz nos fins de semana?", options = listOf(), answers = listOf("cozinha", "ele cozinha", "cozinha nos fins de semana"), explain = "Eu… cozinho nos fins de semana."), Exercise(id = "pt-read-anuncio-colega-q5", kind = "written", prompt = "Quando o Pedro lê?", options = listOf(), answers = listOf("à noite", "a noite", "de noite"), explain = "Trabalho de manhã e leio à noite.")), skills = listOf("reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people")),
    ReadingText(id = "pt-read-mensagem-grupo", languageID = "pt", title = "Mensagens do grupo para o fim de semana", level = "A1", topic = "fim de semana", unitID = "pt-foundations-u13", text = "Mensagens do grupo « Os amigos ». Ana: Chove no sábado ! O que a gente faz ? Leo: Eu caminho de manhã, mas só quando não chove. Bia: Eu gosto de filmes. Vem para casa ! Leo: Boa ! Eu levo o bolo. Nunca como doce, mas sábado é dia. Ana: Eu não gosto de frio. Levo o suco. Até sábado !", questions = listOf(Exercise(id = "pt-read-mensagem-grupo-q1", kind = "choice", prompt = "Como está o tempo no sábado?", options = listOf("Chove", "Faz calor", "Neva", "Está quente"), answers = listOf("Chove"), explain = "Ana: Chove no sábado !"), Exercise(id = "pt-read-mensagem-grupo-q2", kind = "choice", prompt = "Quando o Leo caminha?", options = listOf("De manhã", "À noite", "À tarde", "Nunca"), answers = listOf("De manhã"), explain = "Eu caminho de manhã, mas só quando não chove."), Exercise(id = "pt-read-mensagem-grupo-q3", kind = "choice", prompt = "O que a Bia gosta de fazer?", options = listOf("Ver filmes", "Cozinhar", "Caminhar", "Ler"), answers = listOf("Ver filmes"), explain = "Bia: Eu gosto de filmes. Vem para casa !"), Exercise(id = "pt-read-mensagem-grupo-q4", kind = "written", prompt = "O que o Leo leva para a casa da Bia?", options = listOf(), answers = listOf("o bolo", "ele leva o bolo", "levo o bolo"), explain = "Eu levo o bolo, diz o Leo."), Exercise(id = "pt-read-mensagem-grupo-q5", kind = "written", prompt = "O que a Ana leva?", options = listOf(), answers = listOf("o suco", "ela leva o suco", "levo o suco"), explain = "Levo o suco, diz a Ana."), Exercise(id = "pt-read-mensagem-grupo-q6", kind = "written", prompt = "O que o Leo nunca come?", options = listOf(), answers = listOf("doce", "doce nunca", "nunca como doce"), explain = "Nunca como doce, mas sábado é dia.")), skills = listOf("reading:detail", "reading:scan", "vocab:hobbies", "grammar:frequency-adverbs"))
) }
